// ---------------------------------------------------------------------------
// Pantalla de llamadas · Abrir la pantalla (D43). 2026-10-23.
// Entrada ($json): lo que recibe el Webhook "abrir" (GET). La dirección es
//   .../webhook/llamada?oportunidad_id=15802            (desde WF2 o a mano)
//   .../webhook/llamada?oportunidad_id=15802&ultima=1   (desde WF3, D44; ultima=0 si todavía no)
// n8n guarda lo que va detrás del "?" en $json.query y las cabeceras en $json.headers.
// Salida: el CONTEXTO de la pantalla (mismas claves en todos los nodos que lo crean):
//   { modo, oportunidad_id, ultima, base, fecha_extra, borrador, avisos,
//     final, aviso_tecnico, nodo_error, mensaje_tecnico }
//   modo 'ficha'  -> hay número válido: se lee la ficha y se pinta el formulario
//   modo 'buscar' -> sin número (o mal escrito): solo la caja para escribirlo
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Lo que llegó al webhook (una sola petición = un solo elemento).
const w = $input.first().json;
// Lo que va detrás del "?" ("?? {}": objeto vacío si no hay nada).
const q = w.query ?? {};
// Las cabeceras de la petición (n8n las pone en minúsculas).
const h = w.headers ?? {};

// ---- 1. Dirección pública de la pantalla (base) -----------------------------
// n8n mete las páginas HTML en un iframe aislado, donde las direcciones
// relativas NO funcionan: los enlaces y formularios necesitan la dirección
// completa. Se saca de las cabeceras de ESTA petición (ngrok añade
// x-forwarded-host y x-forwarded-proto), así no se escribe el dominio en
// ningún sitio más (D44: una sola fuente para cada dato).
function baseDe(cab) {
  // El host público: el de ngrok si existe; si no, el de la propia petición.
  const host = String(cab['x-forwarded-host'] ?? cab.host ?? '').split(',')[0].trim();
  // El protocolo: el que dice ngrok (https; puede venir "https,http": se toma el primero).
  // Sin ngrok (n8n abierto en local, http://localhost:5678) no hay cabecera: http.
  const proto = String(cab['x-forwarded-proto'] ?? 'http').split(',')[0].trim();
  // Solo letras, cifras, puntos, guiones y un puerto: cualquier otra cosa se descarta.
  if (!/^[A-Za-z0-9.-]+(:[0-9]{1,5})?$/.test(host)) return '';
  // Solo http o https.
  if (proto !== 'http' && proto !== 'https') return '';
  // La base completa, por ejemplo "https://tu-dominio".
  return `${proto}://${host}`;
}
const base = baseDe(h);

// ---- 2. El número de oportunidad ----------------------------------------------
// La misma regla que la ficha (validar_enlace): solo cifras, sin 0 delante, 1 a 10 cifras.
const texto = String(q.oportunidad_id ?? '').trim();
const valido = /^[1-9][0-9]{0,9}$/.test(texto);

// Aviso solo si se escribió algo que no vale (sin número = pantalla de búsqueda, sin aviso).
const avisos = [];
if (texto !== '' && !valido) avisos.push('El número de oportunidad no es válido: solo lleva cifras.');

// ---- 3. El contexto -------------------------------------------------------------
return [{
  json: {
    modo: valido ? 'ficha' : 'buscar',          // qué pinta la pantalla
    oportunidad_id: valido ? Number(texto) : null,
    // D44: la marca la pone WF3 ('1' = última llamada, '0' = todavía no). Sin marca
    // (número escrito a mano, aviso del Gate): null = no se sabe. La pantalla no calcula nada.
    ultima: q.ultima === '1' ? true : q.ultima === '0' ? false : null,
    base,                                       // dirección pública, para enlaces y formularios
    fecha_extra: '',                            // "Otro día más adelante" (solo en las vueltas por POST)
    borrador: {},                               // lo ya escrito (solo en las vueltas por POST)
    avisos,                                     // textos para la caja de avisos (se escapan al pintar)
    final: null,                                // pantalla final (solo después de registrar)
    aviso_tecnico: false,                       // nada que avisar al técnico todavía
    nodo_error: '',
    mensaje_tecnico: '',
  },
}];

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Punto de encuentro (D43). 2026-10-23.
// Aquí llegan TODOS los caminos que acaban pintando la pantalla:
//   validar_apertura    -> se abre la pantalla (GET)
//   segun_accion        -> "Actualizar horas" u "Otro día" (POST)
//   registro_valido     -> lo enviado no vale: se vuelve a pintar con el aviso
//   segun_traduccion    -> el backend no lo registró (p. ej. hora ocupada) o ya hay pantalla final
//   cerrar_pantalla     -> registrado: pantalla final
// No cambia nada: deja el contexto con un nombre FIJO para que construir_pagina
// lo lea siempre igual con $('contexto'), venga de donde venga.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Solo se queda con el primer elemento (cada camino manda uno) y lo pasa tal cual.
return [{ json: $input.first().json }];

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Construir la página (D43, D44). 2026-10-23.
// Pinta TODAS las pantallas de WF_pantalla_llamadas:
//   modo 'buscar' -> solo la caja para escribir el número (y avisos)
//   modo 'final'  -> el resultado del registro (verde) o un aviso (naranja)
//   modo 'ficha'  -> la ficha y el formulario; o un aviso si no hay nada que registrar
// Lee:
//   $('contexto')          -> qué pintar, lo ya escrito (borrador) y los avisos
//   $('leer_ficha_pagina') -> GET /oportunidades/{id}/ficha (solo en modo 'ficha')
//   $('leer_dias')         -> GET /huecos-libres          (solo en modo 'ficha')
//   $('leer_horas_dia')    -> GET /huecos-libres?fecha=   (solo con "Otro día")
// Los HTTP llevan "On Error: Continue": si no hay respuesta, llega { error }.
// POR QUÉ LA PÁGINA ES ASÍ: n8n (desde 1.103) mete el HTML de un webhook en un
//   iframe aislado: sin direcciones relativas, sin contraseña para fetch(). Por eso
//   la página NO pide datos por su cuenta: todo llega pintado desde aquí, y cada
//   acción (registrar, otro día, actualizar horas) es un formulario normal que
//   abre la página nueva en la ventana entera (target="_top"), con la contraseña
//   que el navegador ya tiene. Lo escrito viaja en el formulario y vuelve pintado.
// Salida: { html, codigo, aviso_tecnico, nodo_error, mensaje_tecnico, oportunidad_id }
// CONFIDENCIAL: la dirección solo vuelve a la misma pantalla que la escribió;
//   nunca va a un aviso técnico (D42.5). Todo texto pasa por esc().
// D46 (2026-10-26): si la llamada ya está registrada pero la ficha trae
//   visita_modificable (visita confirmada y futura), se pinta el MISMO formulario con
//   tres opciones: cambiar día u hora, cancelar la visita o no cambiar nada. Se envía
//   con accion 'visita' (camino nuevo: validar_cambio -> POST /cambios-visita).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// ---- 0. Piezas fijas de la página: estilos, formulario y JavaScript del navegador ----
// Van PRIMERO porque la lógica (secciones 1 a 5) las usa. String.raw guarda el texto
// tal cual. Regla para escribirlas: sin comillas invertidas ni "dólar + llave" dentro,
// porque cortarían el texto; por eso el JavaScript del navegador suma textos con "+".

// Estilos: los colores de la empresa (los mismos que la ficha y los emails).
const CSS = String.raw`
/* Colores de la empresa como variables (los mismos que la ficha y los emails) */
:root{--azul:#0B3C5D;--turquesa:#1F8A8A;--turquesa-claro:#E3F2F1;--texto:#1F2933;--suave:#5B6B79;--borde:#E5E9ED;--fondo:#F4F6F8;
--aviso:#8A4B00;--aviso-fondo:#FFF4E5;--error:#A61B1B;--error-fondo:#FDECEC;--ok:#1E6B3A;--ok-fondo:#E7F5EC}
/* Medidas que incluyen el borde; letra y fondo de toda la página */
*{box-sizing:border-box}
body{margin:0;background:var(--fondo);color:var(--texto);font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.45}
/* Cabecera azul con el título */
.cab{background:var(--azul);color:#fff;padding:14px 24px;display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}
.cab h1{font-size:18px;margin:0}
.cab small{display:block;color:#A7D8D6;font-size:13px;font-weight:normal;margin-top:2px}
/* Caja para escribir el número a mano */
.buscar{display:flex;gap:6px;align-items:center}
.buscar label{font-size:13px;color:#A7D8D6}
.buscar input{width:110px;padding:7px 9px;border-radius:5px;border:0;font-size:15px}
.buscar button{padding:7px 12px;border:0;border-radius:5px;background:var(--turquesa);color:#fff;font-weight:bold;cursor:pointer}
/* Franja turquesa bajo la cabecera */
.franja{height:4px;background:var(--turquesa)}
/* Dos columnas en ordenador (ficha | registro); una sola en avisos y en el móvil */
.contenido{max-width:1100px;margin:20px auto;padding:0 16px;display:grid;grid-template-columns:340px 1fr;gap:20px;align-items:start}
.contenido.una{grid-template-columns:1fr;max-width:720px}
@media (max-width:820px){.contenido{grid-template-columns:1fr}}
/* Tarjeta blanca; la de la ficha se queda fija al bajar */
.tarjeta{background:#fff;border:1px solid var(--borde);border-radius:8px;padding:18px 20px}
.ficha{position:sticky;top:12px}
.titulo-sec{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:var(--turquesa);font-weight:bold;border-bottom:2px solid var(--turquesa-claro);padding-bottom:6px;margin:0 0 10px}
/* Tabla de la ficha: etiqueta gris a la izquierda, valor en negrita */
.ficha table{width:100%;border-collapse:collapse}
.ficha td{padding:5px 0;vertical-align:top;font-size:14px}
.ficha td:first-child{color:var(--suave);font-size:13px;width:42%;padding-right:10px}
.ficha td:last-child{font-weight:bold}
/* Etiqueta del tipo de llamada y cita del cliente */
.etiqueta-llamada{display:inline-block;background:var(--turquesa-claro);color:var(--azul);font-weight:bold;font-size:13px;border-radius:12px;padding:3px 10px;margin-bottom:10px}
.cita{background:var(--fondo);border-left:3px solid var(--turquesa);padding:8px 10px;font-size:14px;font-style:italic;margin-top:4px;white-space:pre-wrap}
/* Enlace a la ficha, pie y textos pequeños */
.enlace{display:inline-block;margin-top:12px;color:var(--turquesa);font-weight:bold;font-size:14px;text-decoration:none}
.pie{font-size:12px;color:var(--suave);margin-top:14px;border-top:1px solid var(--borde);padding-top:10px}
.suave{color:var(--suave)} .peq{font-size:13px;margin-top:8px} .grande{font-size:17px}
/* Pasos del formulario con su número en un círculo */
.paso{margin-bottom:22px}
.paso h2{font-size:16px;margin:0 0 10px;color:var(--azul)}
.paso h2 .num{display:inline-block;width:24px;height:24px;border-radius:50%;background:var(--azul);color:#fff;text-align:center;font-size:13px;line-height:24px;margin-right:8px}
/* Botones grandes de resultado; el elegido se marca (en rojo si es definitivo) */
.opciones{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}
.opcion{border:2px solid var(--borde);border-radius:8px;padding:12px;cursor:pointer;background:#fff;text-align:left;font-size:15px;font-family:inherit;color:var(--texto)}
.opcion small{display:block;color:var(--suave);font-size:12px;margin-top:3px}
.opcion:hover{border-color:var(--turquesa)}
/* Resultado elegido */
.opcion.sel{border-color:var(--turquesa);background:var(--turquesa-claro)}
.opcion.peligro.sel{border-color:var(--error);background:var(--error-fondo)}
/* Agenda: un recuadro por día, con mañana y tarde */
.dias{display:flex;flex-direction:column;gap:8px}
.dia{border:1px solid var(--borde);border-radius:8px;padding:10px 12px}
.dia-cab{font-weight:bold;margin-bottom:6px}
.franjas{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.franjas em{font-style:normal;color:var(--suave);font-size:12px;width:52px}
/* Botones de hora: normal, elegida y bloqueada (la que pidió el cliente) */
.hora{border:1px solid var(--turquesa);background:#fff;color:var(--azul);border-radius:5px;padding:6px 10px;font-size:14px;cursor:pointer;font-family:inherit}
.hora.sel{background:var(--turquesa);color:#fff;font-weight:bold}
.hora.ocupada{border-color:var(--borde);color:#B0B8BF;text-decoration:line-through;cursor:not-allowed}
.otro-dia{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:8px;font-size:14px}
/* Campos de texto */
.campo{margin-bottom:14px}
.campo label{display:block;font-weight:bold;font-size:14px;margin-bottom:5px}
.campo .ayuda{font-weight:normal;color:var(--suave);font-size:12px}
input[type=text],input[type=date],select,textarea{width:100%;padding:9px 10px;border:1px solid #C9D1D8;border-radius:5px;font-size:15px;font-family:inherit;color:var(--texto)}
/* Cajas grandes y fila del código postal y el municipio */
textarea{min-height:90px;resize:vertical}
.fila-dir{display:grid;grid-template-columns:150px 1fr;gap:10px}
@media (max-width:520px){.fila-dir{grid-template-columns:1fr}}
.contador{float:right;font-weight:normal;color:var(--suave);font-size:12px}
/* Comprobación mientras se escribe: verde bien, rojo mal */
.estado-campo{font-size:13px;margin-top:4px;min-height:18px}
.estado-campo.bien{color:var(--ok)} .estado-campo.mal{color:var(--error)}
input.mal{border-color:var(--error);background:#FFF8F8} input.bien{border-color:var(--ok)}
/* Cajas de aviso: naranja (por defecto), rojo y verde */
.aviso{background:var(--aviso-fondo);border:1px solid #F0C98A;color:var(--aviso);border-radius:6px;padding:10px 12px;font-size:14px;margin-bottom:12px}
.aviso.rojo{background:var(--error-fondo);border-color:#F2B8B8;color:var(--error)}
.aviso.verde{background:var(--ok-fondo);border-color:#A9D8B8;color:var(--ok)}
/* Botones de acción */
.botonera{display:flex;gap:10px;flex-wrap:wrap;margin-top:6px}
.btn{padding:11px 18px;border-radius:6px;border:0;font-size:15px;font-weight:bold;cursor:pointer;font-family:inherit}
.btn.principal{background:var(--azul);color:#fff} .btn.principal:disabled{background:#9AA8B4;cursor:not-allowed}
.btn.secundario{background:#fff;color:var(--azul);border:2px solid var(--azul)}
/* Botón rojo (definitivo), pequeño y la línea de "Falta: ..." */
.btn.peligro{background:var(--error);color:#fff}
.btn.peq{padding:5px 10px;font-size:13px}
.faltan{font-size:13px;color:var(--suave);margin-top:8px}
/* Resumen antes de registrar: tabla etiqueta | valor */
.resumen table{width:100%;border-collapse:collapse;margin-bottom:14px}
.resumen td{padding:8px 0;border-bottom:1px solid var(--borde);vertical-align:top;font-size:15px}
.resumen td:first-child{color:var(--suave);width:34%;padding-right:12px;font-size:14px}
/* La dirección, campo a campo; y la clase que esconde lo que no toca */
.resumen .dir div{margin-bottom:6px}
.resumen .dir span{display:inline-block;min-width:118px;color:var(--suave);font-size:13px}
.oculto{display:none}
`;

// El formulario (vacío: lo rellena y lo enseña el JavaScript según el resultado elegido).
const FORMULARIO = String.raw`
<!-- Todo el formulario; el JavaScript enseña solo los pasos del resultado elegido -->
<div id="formulario">
  <!-- Paso 1: los botones de resultado (los pinta pintarOpciones) -->
  <div class="paso"><h2><span class="num">1</span><span id="titulo-paso1">¿Cómo ha ido la llamada?</span></h2><div class="opciones" id="opciones"></div></div>
  <!-- Paso 2 (visita acordada / otra hora): la agenda -->
  <div class="paso oculto" id="paso-agenda">
    <h2><span class="num">2</span><span id="titulo-agenda">Día y hora de la visita</span>
      <button type="button" class="btn secundario peq" style="float:right" data-accion="actualizar">↻ Actualizar horas</button></h2>
    <!-- D46: al cambiar, la visita que tiene ahora (la pinta elegir) -->
    <div id="texto-visita-actual"></div>
    <!-- Avisos de la agenda y la explicación -->
    <div id="aviso-agenda"></div>
    <p class="suave" style="margin:0 0 8px;font-size:14px">Horas libres en los próximos días laborables. Pulsa la que acuerdes con el cliente.</p>
    <!-- Los días con sus horas (los pinta pintarDias) -->
    <div class="dias" id="dias"></div>
    <!-- Otro día más adelante: se elige la fecha y la página vuelve con sus horas -->
    <div class="otro-dia">Otro día más adelante:
      <input type="date" id="otra-fecha" style="width:auto">
      <button type="button" class="btn secundario peq" data-accion="otro-dia">Ver sus horas</button></div>
  </div>
  <!-- Paso 2 (confirmar la hora pedida): solo se enseña la hora -->
  <div class="paso oculto" id="paso-hora-pedida"><h2><span class="num">2</span>Hora que pidió el cliente</h2><div class="aviso verde" id="texto-hora-pedida"></div></div>
  <!-- Paso 3 (si queda visita): la dirección de la obra, obligatoria (D42) -->
  <div class="paso oculto" id="paso-direccion">
    <h2><span class="num">3</span>Dirección de la obra</h2>
    <!-- Calle y número -->
    <div class="campo"><label for="calle">Calle y número <span class="ayuda">(con piso y puerta si los hay)</span></label>
      <input type="text" id="calle" maxlength="150" autocomplete="off"><div class="estado-campo" id="estado-calle"></div></div>
    <!-- Código postal y municipio, en la misma fila -->
    <div class="fila-dir">
      <div class="campo"><label for="cp">Código postal</label>
        <input type="text" id="cp" inputmode="numeric" maxlength="5" autocomplete="off"><div class="estado-campo" id="estado-cp"></div></div>
      <!-- Municipio -->
      <div class="campo"><label for="municipio">Municipio</label>
        <input type="text" id="municipio" maxlength="100" autocomplete="off"><div class="estado-campo" id="estado-municipio"></div></div>
    </div>
  </div>
  <!-- Paso 2 (descartar / el cliente cancela): el motivo, con su aviso de "definitivo" -->
  <div class="paso oculto" id="paso-motivo">
    <h2><span class="num">2</span>Motivo</h2><div class="aviso rojo" id="aviso-definitivo"></div>
    <div id="aviso-sin-decidir"></div>
    <div class="campo"><select id="motivo"></select></div>
  </div>
  <!-- Último paso: el informe (siempre) y el mensaje para el cliente (solo si queda visita) -->
  <div class="paso oculto" id="paso-informe">
    <h2><span class="num" id="num-informe">4</span>Informe y mensaje</h2>
    <!-- Informe: lo que se habló (obligatorio, máximo 2.000) -->
    <div class="campo"><label for="informe">Informe de la llamada <span class="contador" id="cont-informe">0 / 2000</span></label>
      <textarea id="informe" maxlength="2000" placeholder="Qué se habló, qué se acordó y dudas del cliente."></textarea></div>
    <!-- Mensaje para el email del cliente (opcional, máximo 500) -->
    <div class="campo" id="campo-mensaje"><label for="mensaje">Mensaje para el cliente <span class="ayuda">(opcional; aparecerá en su email)</span>
      <span class="contador" id="cont-mensaje">0 / 500</span></label>
      <textarea id="mensaje" maxlength="500" placeholder="Por ejemplo, qué preparar para la visita o cómo acceder al edificio. Nada de valoraciones internas."></textarea></div>
  </div>
  <!-- "No contesta o se lo piensa": solo el texto de qué pasa ahora -->
  <div class="paso oculto" id="paso-sin-registro"><div class="aviso" id="texto-sin-registro"></div></div>
  <!-- Botón para pasar al resumen y la línea de "Falta: ..." -->
  <div class="botonera"><button type="button" class="btn principal" id="btn-revisar" disabled data-accion="revisar">Revisar antes de registrar</button></div>
  <div class="faltan" id="faltan"></div>
</div>
<!-- El resumen antes de registrar (sustituye al formulario; "Volver a editar" no borra nada) -->
<div class="resumen oculto" id="resumen">
  <h2 style="font-size:17px;color:var(--azul);margin:0 0 12px">Comprueba antes de registrar</h2>
  <div id="resumen-aviso"></div><table id="resumen-tabla"></table>
  <!-- Registrar (envía) o volver a editar -->
  <div class="botonera"><button type="button" class="btn principal" id="btn-registrar" data-accion="registrar">Sí, registrar</button>
    <button type="button" class="btn secundario" data-accion="volver">Volver a editar</button></div>
</div>
<!-- Mensaje de "Cerrar sin registrar" -->
<div class="oculto" id="final"></div>
`;

// El JavaScript del navegador. Solo enseña, comprueba y ENVÍA formularios normales:
// no pide datos por su cuenta (el iframe de n8n no lo permite) y no decide nada:
// lo que se registra lo vuelven a comprobar validar_registro y el backend.
const SCRIPT = String.raw`
// Los datos que ha pintado n8n (JSON, no HTML).
var D = JSON.parse(document.getElementById('datos').textContent);
// Atajo para buscar un elemento por su id.
function el(id) { return document.getElementById(id); }
// Escapar texto antes de meterlo en HTML (lo escrito por personas).
function esc(v) { return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }

// Textos de cada resultado; sin_registro NO es un resultado del backend: no se envía.
// visita = queda una visita (pide dirección); agenda = se elige día y hora; peligro = definitivo.
var RES = {
  visita_acordada: { texto: 'Visita acordada', ayuda: 'Se elige día y hora', visita: true, agenda: true },
  descartar: { texto: 'Descartar', ayuda: 'Definitivo: cierra la oportunidad', peligro: true },
  confirmar_hora: { texto: 'Confirmar la hora pedida', ayuda: 'Se queda la que eligió el cliente', visita: true },
  otra_hora: { texto: 'Otra hora', ayuda: 'La pedida se cancela', visita: true, agenda: true },
  // (sigue la lista) los dos de abajo: cancelar (definitivo) y "no registrar nada"
  cliente_cancela: { texto: 'El cliente cancela', ayuda: 'Definitivo: cierra la oportunidad', peligro: true },
  sin_registro: { texto: 'No contesta o se lo piensa', ayuda: 'No se registra nada', nada: true },
  // D46: visita YA confirmada. mensaje = pide el mensaje para el email, sin pedir la dirección.
  cambiar_visita: { texto: 'Cambiar día u hora', ayuda: 'La hora actual se anula', agenda: true, mensaje: true },
  cancelar_visita: { texto: 'Cancelar la visita', ayuda: 'Definitivo: cierra la oportunidad', peligro: true },
  sin_cambio: { texto: 'No cambiar nada', ayuda: 'La visita sigue como está', nada: true }
};
// Motivos: [código del backend, texto]. Al cancelar no valen "no contesta" ni "sin decidirse" (D29.3).
var MOT_DESCARTAR = [['precio', 'Precio: le parece caro'], ['plazo', 'Plazo: no le encajan los tiempos'],
  ['no_contesta', 'No contesta (tras varios intentos)'], ['sin_decision', 'Sigue sin decidirse (última llamada)'],
  ['proyecto_no_viable', 'Proyecto no viable técnicamente'], ['otro', 'Otro (explícalo en el informe)']];
// Los cuatro motivos admitidos cuando el cliente cancela.
var MOT_CANCELA = [['precio', 'Precio: le parece caro'], ['plazo', 'Plazo: no le encajan los tiempos'],
  ['proyecto_no_viable', 'Proyecto no viable técnicamente'], ['otro', 'Otro (explícalo en el informe)']];
// Primeras 2 cifras del código postal -> provincia (para comprobarlo mientras se escribe).
var PROV = {'01':'Álava','02':'Albacete','03':'Alicante','04':'Almería','05':'Ávila','06':'Badajoz','07':'Illes Balears','08':'Barcelona','09':'Burgos','10':'Cáceres','11':'Cádiz','12':'Castellón','13':'Ciudad Real','14':'Córdoba','15':'A Coruña','16':'Cuenca','17':'Girona','18':'Granada','19':'Guadalajara','20':'Gipuzkoa','21':'Huelva','22':'Huesca','23':'Jaén','24':'León','25':'Lleida','26':'La Rioja','27':'Lugo','28':'Madrid','29':'Málaga','30':'Murcia','31':'Navarra','32':'Ourense','33':'Asturias','34':'Palencia','35':'Las Palmas','36':'Pontevedra','37':'Salamanca','38':'Santa Cruz de Tenerife','39':'Cantabria','40':'Segovia','41':'Sevilla','42':'Soria','43':'Tarragona','44':'Teruel','45':'Toledo','46':'Valencia','47':'Valladolid','48':'Bizkaia','49':'Zamora','50':'Zaragoza','51':'Ceuta','52':'Melilla'};

var eleccion = null;   // resultado elegido
var visita = null;     // { fecha, hora, legible } elegida
var enviando = false;  // evita enviar dos veces (doble clic)

// ---- Botones de resultado: solo los que admite el backend para esta llamada ----
function pintarOpciones() {
  var h = '';                                                   // el HTML de los botones
  D.resultados.forEach(function (r) {                           // uno por resultado admitido
    var o = RES[r]; if (!o) return;                             // un resultado desconocido no se pinta
    h += '<button type="button" class="opcion' + (o.peligro ? ' peligro' : '') + (eleccion === r ? ' sel' : '') +
      '" data-resultado="' + r + '">' + o.texto + '<small>' + o.ayuda + '</small></button>';   // botón con su ayuda
  });
  el('opciones').innerHTML = h;                                 // se ponen en la página
}

// ---- Agenda: un botón por hora libre ----
function botonHora(d, h) {
  // La hora que no se puede volver a elegir (el backend daría 422): en "Otra hora", la que
  // pidió el cliente; en "Cambiar día u hora" (D46), la que tiene ahora la visita.
  var vp = eleccion === 'otra_hora' ? D.visita_pedida : eleccion === 'cambiar_visita' ? D.visita_actual : null;
  if (vp && vp.fecha === d.fecha && vp.hora === h) {
    return '<button type="button" class="hora ocupada" title="' + (eleccion === 'otra_hora' ? 'Es la hora que pidió el cliente' : 'Es la hora que tiene ahora') + '">' + h + '</button>';
  }
  var sel = visita && visita.fecha === d.fecha && visita.hora === h;          // ¿es la elegida?
  return '<button type="button" class="hora' + (sel ? ' sel' : '') + '" data-fecha="' + d.fecha + '" data-hora="' + h + '">' + h + '</button>';
}
// Pinta todos los días con sus horas de mañana y de tarde.
function pintarDias() {
  var h = '';                                                   // el HTML de la agenda
  D.dias.forEach(function (d) {                                 // un recuadro por día
    h += '<div class="dia"><div class="dia-cab">' + esc(d.titulo) + (d.extra ? ' <span class="suave">(otro día)</span>' : '') + '</div><div class="franjas">';
    if (d.manana.length) h += '<em>Mañana</em>' + d.manana.map(function (x) { return botonHora(d, x); }).join('');   // horas de mañana
    if (d.tarde.length) h += '<em style="margin-left:' + (d.manana.length ? 10 : 0) + 'px">Tarde</em>' + d.tarde.map(function (x) { return botonHora(d, x); }).join('');   // de tarde
    h += '</div></div>';                                        // se cierra el recuadro
  });
  el('dias').innerHTML = h;                                     // se pone en la página
  if (D.aviso_agenda) el('aviso-agenda').innerHTML = '<div class="aviso">⚠️ ' + esc(D.aviso_agenda) + '</div>';   // aviso de n8n
}
// Elegir una hora: solo si está en la lista que dio el backend.
function elegirHora(fecha, hora) {
  var d = D.dias.filter(function (x) { return x.fecha === fecha; })[0];       // el día de esa fecha
  if (!d || (d.manana.indexOf(hora) < 0 && d.tarde.indexOf(hora) < 0)) return;   // ya no está libre: nada
  visita = { fecha: fecha, hora: hora, legible: d.titulo.toLowerCase() + '/' + fecha.slice(0, 4) + ' a las ' + hora };   // "lunes 26/10/2026 a las 10:30"
  pintarDias(); comprobar();                                    // se marca y se revisa qué falta
}

// ---- Elegir un resultado: enseña solo lo que ese resultado necesita ----
function elegir(r) {
  var o = RES[r]; if (!o) return;                               // resultado desconocido: nada
  eleccion = r; visita = null;                                  // al cambiar de resultado, la hora se vuelve a elegir
  var definitivo = !!o.peligro;                                 // descartar o cancelar
  // Qué pasos se ven con este resultado (toggle con true = esconder).
  el('paso-agenda').classList.toggle('oculto', !o.agenda);
  el('paso-hora-pedida').classList.toggle('oculto', r !== 'confirmar_hora');
  el('paso-direccion').classList.toggle('oculto', !o.visita);
  el('paso-motivo').classList.toggle('oculto', !definitivo);
  // El informe (no en "sin registro"), el mensaje (solo con visita) y el texto de "sin registro".
  el('paso-informe').classList.toggle('oculto', !!o.nada);
  el('campo-mensaje').classList.toggle('oculto', !(o.visita || o.mensaje));   // D46: también al cambiar la hora
  el('paso-sin-registro').classList.toggle('oculto', !o.nada);
  el('num-informe').textContent = o.visita ? '4' : '3';         // con dirección (paso 3) el informe es el 4
  el('btn-revisar').textContent = o.nada ? 'Cerrar sin registrar' : 'Revisar antes de registrar';
  // D46: al cambiar, la agenda dice que es la NUEVA hora y enseña la que tiene ahora.
  el('titulo-agenda').textContent = r === 'cambiar_visita' ? 'Nuevo día y hora' : 'Día y hora de la visita';
  el('texto-visita-actual').innerHTML = r === 'cambiar_visita' && D.visita_actual
    ? '<div class="aviso">Ahora tiene la visita el <strong>' + esc(D.visita_actual.legible) + '</strong>. Elige la nueva hora con el cliente.</div>' : '';
  // Confirmar la hora pedida: la visita es la pedida (el servidor la vuelve a leer de la ficha).
  if (r === 'confirmar_hora' && D.visita_pedida) {
    visita = { fecha: D.visita_pedida.fecha, hora: D.visita_pedida.hora, legible: D.visita_pedida.legible };
    el('texto-hora-pedida').innerHTML = 'Se confirmará: <strong>' + esc(D.visita_pedida.legible) + '</strong>';
  }
  // Descartar o cancelar: la lista de motivos que toca y el aviso de "definitivo".
  if (definitivo) {
    var lista = r === 'descartar' ? MOT_DESCARTAR : MOT_CANCELA;  // qué motivos valen
    var previo = el('motivo').value;                            // el motivo que ya estaba elegido
    el('motivo').innerHTML = '<option value="">— Elige el motivo —</option>' + lista.map(function (m) {
      return '<option value="' + m[0] + '">' + m[1] + '</option>'; }).join('');   // una opción por motivo
    if (lista.some(function (m) { return m[0] === previo; })) el('motivo').value = previo;   // se conserva si vale
    el('aviso-definitivo').innerHTML = r === 'descartar'        // el aviso, según el resultado
      ? '⚠️ <strong>Descartar es definitivo.</strong> Usa "No contesta" solo después de 3 intentos en 2 días laborables distintos, y "Sigue sin decidirse" solo en la última llamada.'
      : r === 'cancelar_visita'                                 // D46: la visita ya estaba confirmada
        ? '⚠️ <strong>Es definitivo:</strong> la visita confirmada se cancela, se quita del calendario y la oportunidad queda cerrada como perdida. Si el cliente solo quiere otro día, elige "Cambiar día u hora".'
        : '⚠️ <strong>Es definitivo:</strong> la visita pedida se cancela y la oportunidad queda cerrada como perdida.';
  }
  // "No contesta o se lo piensa" (o "No cambiar nada"): qué pasa ahora, con las palabras de administración.
  if (o.nada) {
    var t = '<strong>No se registra nada.</strong> ';           // siempre igual al principio
    if (r === 'sin_cambio') t = '<strong>No se cambia nada.</strong> La visita sigue confirmada el ' + esc(D.visita_actual ? D.visita_actual.legible : '') + '.';
    else if (D.tipo_llamada === 'confirmacion_visita') t += 'La visita pedida sigue pendiente y volverá a salir en el email diario.';
    else if (D.ultima === '1') t += 'La oportunidad sigue pendiente.<br>⚠️ <strong>Ya es la última llamada.</strong> Si no contesta tras 3 intentos en 2 días laborables distintos, o sigue sin decidirse, descártala.';
    else t += 'La oportunidad sigue pendiente y volverá a salir en el email diario, que te avisará cuando toque la última llamada.';
    el('texto-sin-registro').innerHTML = t;                     // se pone en la página
  }
  avisoSinDecidir(); pintarOpciones(); pintarDias(); comprobar();   // se repinta y se revisa qué falta
}

// ---- "Sigue sin decidirse" antes de tiempo: solo si el email diario dijo que NO es la última (D44) ----
function avisoSinDecidir() {
  var temprano = eleccion === 'descartar' && el('motivo').value === 'sin_decision' && D.ultima === '0';   // '' = no se sabe: sin aviso
  el('aviso-sin-decidir').innerHTML = temprano
    ? '<div class="aviso">⚠️ Según el email diario, todavía <strong>no</strong> es la última llamada. Si se lo está pensando, elige "No contesta o se lo piensa".</div>' : '';
}

// ---- La dirección, comprobada MIENTRAS SE ESCRIBE (mismas reglas que el backend, D42.3) ----
// Marca un campo: 'bien' (verde), 'mal' (rojo) o nada, con un texto debajo.
function marcar(campo, estado, texto) {
  el(campo).classList.remove('bien', 'mal'); if (estado) el(campo).classList.add(estado);   // color del borde
  var e = el('estado-' + campo); e.className = 'estado-campo ' + (estado || ''); e.textContent = texto;   // texto debajo
}
// ¿Está completa y bien la dirección? Marca cada campo y devuelve true o false.
function direccionOk() {
  var calle = el('calle').value.trim(), cp = el('cp').value.trim(), mun = el('municipio').value.trim(), ok = true;   // lo escrito, sin espacios de sobra
  if (!calle) { marcar('calle', null, ''); ok = false; } else marcar('calle', 'bien', '');   // calle: no vacía
  if (!cp) { marcar('cp', null, ''); ok = false; }                                         // CP vacío: sin texto
  else if (!/^\d+$/.test(cp)) { marcar('cp', 'mal', 'Solo números.'); ok = false; }         // CP con letras
  else if (cp.length < 5) { marcar('cp', null, cp.length === 4 ? 'Falta 1 cifra.' : 'Faltan ' + (5 - cp.length) + ' cifras.'); ok = false; }   // CP corto
  else if (!PROV[cp.slice(0, 2)]) { marcar('cp', 'mal', 'No existe ningún código postal que empiece por ' + cp.slice(0, 2) + '.'); ok = false; }   // provincia inexistente
  else marcar('cp', 'bien', '✓ ' + PROV[cp.slice(0, 2)]);                                   // CP bien: se dice la provincia
  if (!mun) { marcar('municipio', null, ''); ok = false; } else marcar('municipio', 'bien', '');   // municipio: no vacío
  return ok;
}

// ---- ¿Se puede pasar al resumen? Dice qué falta en vez de dejar un botón muerto ----
function comprobar() {
  var faltan = [];                                              // lo que falta, en palabras
  if (!eleccion) faltan.push('el resultado de la llamada');     // sin resultado no hay nada más
  else {
    var o = RES[eleccion];                                      // qué pide este resultado
    if (o.agenda && !visita) faltan.push('el día y la hora');
    if (o.visita && !direccionOk()) faltan.push('la dirección completa');
    if (o.peligro && !el('motivo').value) faltan.push('el motivo');
    if (!o.nada && !el('informe').value.trim()) faltan.push('el informe');
  }
  el('cont-informe').textContent = el('informe').value.length + ' / 2000';   // contadores de caracteres
  el('cont-mensaje').textContent = el('mensaje').value.length + ' / 500';
  el('btn-revisar').disabled = faltan.length > 0;               // el botón solo se activa si no falta nada
  el('faltan').textContent = faltan.length ? 'Falta: ' + faltan.join(', ') + '.' : '';   // y dice qué falta
}

// ---- Resumen antes de registrar (la dirección campo a campo, D43.7) ----
function revisar() {
  var o = RES[eleccion];                                        // qué se ha elegido
  if (o.nada) {                                                 // nada que enviar: se dice y se cierra
    el('formulario').classList.add('oculto'); el('final').classList.remove('oculto');
    el('final').innerHTML = eleccion === 'sin_cambio'           // D46: la visita confirmada sigue igual
      ? '<div class="aviso"><strong class="grande">No se ha cambiado nada</strong><br>La visita de la oportunidad ' +
        esc(D.oportunidad_id) + ' sigue confirmada el ' + esc(D.visita_actual ? D.visita_actual.legible : '') + '.</div>'
      : '<div class="aviso"><strong class="grande">No se ha registrado nada</strong><br>La oportunidad ' +
        esc(D.oportunidad_id) + ' sigue pendiente y saldrá en el email diario.</div>';
    return;
  }
  // Etiquetas del resultado (las definitivas, en mayúsculas).
  var ET = { visita_acordada: 'Visita acordada', descartar: 'DESCARTAR (definitivo)', confirmar_hora: 'Confirmar la hora pedida',
    otra_hora: 'Otra hora (la pedida se cancela)', cliente_cancela: 'EL CLIENTE CANCELA (definitivo)',
    cambiar_visita: 'Cambiar día u hora', cancelar_visita: 'CANCELAR LA VISITA (definitivo)' };
  var f = '<tr><td>Oportunidad</td><td><strong>' + esc(D.oportunidad_id) + '</strong></td></tr>' +
    '<tr><td>' + (D.modo_visita ? 'Acción' : 'Resultado') + '</td><td><strong>' + ET[eleccion] + '</strong></td></tr>';   // número y resultado
  if (D.modo_visita) {                                          // D46: la visita de ahora y, al cambiar, la nueva
    f += '<tr><td>Visita actual</td><td><strong>' + esc(D.visita_actual.legible) + '</strong>' + (o.agenda ? ' (se anula)' : '') + '</td></tr>';
    if (o.agenda) f += '<tr><td>Nueva visita</td><td><strong>' + esc(visita.legible) + '</strong></td></tr>';
  }
  if (o.visita) {                                               // con visita: día y dirección campo a campo
    var cp = el('cp').value.trim();
    f += '<tr><td>Visita</td><td><strong>' + esc(visita.legible) + '</strong></td></tr>' +
      '<tr><td>Dirección de la obra</td><td class="dir">' +
      '<div><span>Calle y número</span><strong>' + esc(el('calle').value.trim()) + '</strong></div>' +
      '<div><span>Código postal</span><strong>' + esc(cp) + '</strong> (' + esc(PROV[cp.slice(0, 2)] || '') + ')</div>' +
      '<div><span>Municipio</span><strong>' + esc(el('municipio').value.trim()) + '</strong></div></td></tr>';
  } else if (o.peligro) {                                       // descartar o cancelar: el motivo (su texto)
    f += '<tr><td>Motivo</td><td><strong>' + esc(el('motivo').options[el('motivo').selectedIndex].text) + '</strong></td></tr>';
  }
  f += '<tr><td>Informe</td><td>' + esc(el('informe').value.trim()).replace(/\n/g, '<br>') + '</td></tr>';   // el informe, con sus saltos de línea
  if (o.visita || o.mensaje) {                                  // el mensaje: lo que leerá el cliente, o que no hay
    var m = el('mensaje').value.trim();
    f += '<tr><td>Mensaje para el cliente</td><td>' + (m ? esc(m).replace(/\n/g, '<br>') : '<em class="suave">Sin mensaje: el email saldrá sin nota</em>') + '</td></tr>';
  }
  el('resumen-tabla').innerHTML = f;                            // la tabla del resumen
  // Qué pasará al registrar: definitivo (rojo), cambio de hora (D46) o visita nueva.
  el('resumen-aviso').innerHTML = o.peligro ? '<div class="aviso rojo">⚠️ Esto es <strong>definitivo</strong>: no se podrá cambiar después.</div>'
    : eleccion === 'cambiar_visita'
      ? '<div class="aviso">Al registrar, se quita del calendario la hora actual, se añade la nueva y se envía al cliente un email con la nueva fecha.</div>'
      : '<div class="aviso">Al registrar, se crea el evento en el calendario y se envía el email al cliente.</div>';
  el('btn-registrar').className = 'btn ' + (o.peligro ? 'peligro' : 'principal');   // botón rojo si es definitivo
  el('formulario').classList.add('oculto'); el('resumen').classList.remove('oculto');   // se cambia el formulario por el resumen
  window.scrollTo(0, 0);                                        // y se sube arriba
}
// "Volver a editar": se vuelve al formulario sin borrar nada.
function volver() { el('resumen').classList.add('oculto'); el('formulario').classList.remove('oculto'); }

// ---- Enviar: un formulario normal que abre la respuesta en la ventana entera ----
// accion 'registrar' -> registra; 'horas' -> vuelve a pintar con las horas al día (u otro día).
// Lo escrito viaja siempre: si la página vuelve, vuelve rellena.
function enviar(accion, fechaExtra) {
  if (enviando) return; enviando = true;                        // un solo envío (doble clic)
  if (accion === 'registrar') { el('btn-registrar').disabled = true; el('btn-registrar').textContent = 'Registrando…'; }
  // Todos los campos, como texto (el servidor los vuelve a comprobar).
  // D46: con una visita confirmada, "registrar" va por el camino de los cambios ('visita'),
  // con la fecha y hora que el operador VE (si alguien la cambió mientras tanto, el backend da 409).
  if (accion === 'registrar' && D.modo_visita) accion = 'visita';
  var campos = { accion: accion, oportunidad_id: D.oportunidad_id, ultima: D.ultima, fecha_extra: fechaExtra || '',
    fecha_actual: D.visita_actual ? D.visita_actual.fecha : '', hora_actual: D.visita_actual ? D.visita_actual.hora : '',
    resultado: eleccion && !RES[eleccion].nada ? eleccion : '', fecha: visita ? visita.fecha : '', hora: visita ? visita.hora : '',
    calle: el('calle').value, cp: el('cp').value, municipio: el('municipio').value, motivo: el('motivo').value,
    informe: el('informe').value, mensaje: el('mensaje').value };
  var form = document.createElement('form');                    // un formulario invisible
  form.method = 'POST'; form.action = D.url_enviar; form.target = '_top';   // POST a n8n, en la ventana entera
  Object.keys(campos).forEach(function (k) {                    // un campo oculto por dato
    var i = document.createElement('input'); i.type = 'hidden'; i.name = k; i.value = campos[k] == null ? '' : String(campos[k]);
    form.appendChild(i);
  });
  document.body.appendChild(form); form.submit();               // se envía
}
// "Otro día más adelante": la fecha se comprueba aquí antes de pedirla (fin de semana).
function verOtroDia() {
  var f = el('otra-fecha').value;                               // "AAAA-MM-DD" o vacío
  if (!/^\d{4}-\d{2}-\d{2}$/.test(f)) { el('aviso-agenda').innerHTML = '<div class="aviso">Elige primero una fecha.</div>'; return; }
  var ds = new Date(Date.UTC(+f.slice(0, 4), +f.slice(5, 7) - 1, +f.slice(8, 10))).getUTCDay();   // 0 domingo ... 6 sábado
  if (ds === 0 || ds === 6) { el('aviso-agenda').innerHTML = '<div class="aviso">⚠️ Es fin de semana: no hay visitas. Elige otro día.</div>'; return; }
  enviar('horas', f);                                           // la página vuelve con las horas de ese día
}

// ---- Clics: uno solo para toda la página (sin onclick dentro del HTML) ----
document.addEventListener('click', function (ev) {
  var b = ev.target.closest('button'); if (!b) return;          // solo interesan los botones
  if (b.dataset.resultado) return elegir(b.dataset.resultado);  // botón de resultado
  if (b.dataset.hora) return elegirHora(b.dataset.fecha, b.dataset.hora);   // botón de hora
  var a = b.dataset.accion;                                     // botones de acción
  if (a === 'revisar') return revisar();
  if (a === 'volver') return volver();
  if (a === 'registrar') return enviar('registrar', '');
  if (a === 'actualizar') return enviar('horas', D.fecha_extra);   // mantiene el "otro día" si lo había
  if (a === 'otro-dia') return verOtroDia();
});
// Al escribir, se revisa qué falta; al cambiar el motivo, también el aviso de "sin decidirse".
['calle', 'cp', 'municipio', 'informe', 'mensaje'].forEach(function (id) { el(id).addEventListener('input', comprobar); });
el('motivo').addEventListener('change', function () { avisoSinDecidir(); comprobar(); });

// ---- Al abrir: se pinta todo y se recupera lo ya escrito (vuelta tras "horas" o tras un aviso) ----
// D46: con una visita confirmada, la pregunta es qué quiere hacer el cliente con ella.
if (D.modo_visita) el('titulo-paso1').textContent = '¿Qué quiere hacer el cliente con su visita?';
pintarOpciones(); pintarDias();                                 // botones y agenda
var B = D.borrador || {};                                       // lo escrito antes (vacío la primera vez)
el('calle').value = B.calle || ''; el('cp').value = B.cp || ''; el('municipio').value = B.municipio || '';   // la dirección
el('informe').value = B.informe || ''; el('mensaje').value = B.mensaje || '';   // el informe y el mensaje
if (B.resultado && D.resultados.indexOf(B.resultado) >= 0) {    // si había resultado elegido y sigue admitido
  if (B.motivo) el('motivo').innerHTML = '<option value="' + esc(B.motivo) + '"></option>';   // para que elegir() lo conserve
  elegir(B.resultado);                                          // se vuelve a elegir
  if (B.fecha && B.hora && RES[B.resultado].agenda) elegirHora(B.fecha, B.hora);   // la hora, solo si sigue libre
}
comprobar();                                                    // y se dice qué falta
`;

// ---- 1. Lo que hay que pintar ---------------------------------------------------
const ctx = $('contexto').first().json;
// Lee la salida de un nodo; si ese nodo no se ha ejecutado en esta ejecución, null.
function leer(nodo) {
  try { return $(nodo).first().json; } catch (e) { return null; }
}
const enFicha = ctx.modo === 'ficha';
const f = enFicha ? leer('leer_ficha_pagina') : null;                    // la ficha
const rd = enFicha ? leer('leer_dias') : null;                           // los días con horas libres
const rx = enFicha && ctx.fecha_extra ? leer('leer_horas_dia') : null;   // "Otro día más adelante"

// Avisos técnicos: los que ya traía el contexto y los que se encuentren aquí.
const tecnicos = [];
if (ctx.aviso_tecnico) tecnicos.push({ nodo: ctx.nodo_error, texto: ctx.mensaje_tecnico });

// ---- 2. Utilidades ----------------------------------------------------------------
// Escapar texto antes de meterlo en HTML: nombres, informes y textos de visitas
// los escribieron personas y podrían llevar código HTML.
function esc(valor) {
  return String(valor ?? '')
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')     // < y > : impiden abrir etiquetas
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')   // comillas: impiden salir de un atributo
    .replace(/'/g, '&#39;');
}
// Texto de un error de n8n (solo code y message: nunca el objeto entero).
function textoError(e) {
  if (!e) return 'sin detalle';                                // no llegó nada
  if (typeof e === 'string') return e;                         // ya es un texto
  const partes = [e.code, e.message].filter((x) => typeof x === 'string' && x.trim() !== '');
  return partes.length ? partes.join(' · ') : 'error sin texto';
}
// Formatos españoles (solo para MOSTRAR).
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });
const dinero = (t) => (t === null || t === undefined ? '—' : eur.format(Number(t)));
// Fecha con hora, en hora de Madrid.
function fecha(t) {
  if (!t) return '—';                                          // sin fecha: una raya
  return new Date(t).toLocaleString('es-ES', { timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit',
    month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}
// Días enteros desde una fecha (el MISMO cálculo que "hace X días" del email diario).
const diasDesde = (t) => Math.floor((Date.now() - new Date(t).getTime()) / 86400000);
// "jueves" + "2026-10-29" -> "Jueves 29/10" (texto recortado: ninguna zona horaria mueve el día).
function tituloDia(diaSemana, f) {
  const d = String(diaSemana ?? '');
  return `${d.charAt(0).toUpperCase()}${d.slice(1)} ${String(f).slice(8, 10)}/${String(f).slice(5, 7)}`;
}
// Solo horas "HH:MM" (lo demás se descarta).
const horas = (lista) => (Array.isArray(lista) ? lista : []).filter((h) => typeof h === 'string' && /^\d{2}:\d{2}$/.test(h));

// Diccionarios: códigos del backend -> texto.
const TIPOS = { bano: 'Baño', cocina: 'Cocina', integral_vivienda: 'Reforma integral de vivienda', parcial_acabados: 'Acabados parciales' };
// Acabados, tipo de llamada, resultado y estado de la oportunidad.
const ACABADOS = { basico: 'básico', medio: 'medio', alto: 'alto' };
const TIPOS_LLAMADA = { gate: 'Gate (aprobación manual)', seguimiento: 'Seguimiento del presupuesto', confirmacion_visita: 'Confirmación de visita pedida' };
// Resultados ya registrados y estados de la oportunidad (para los avisos).
const RESULTADOS = { visita_acordada: 'Visita acordada', descartar: 'Descartado', confirmar_hora: 'Hora confirmada',
  otra_hora: 'Otra hora acordada', cliente_cancela: 'El cliente cancela' };
const ESTADOS = { nueva: 'nueva', cualificada: 'cualificada', pendiente_aprobacion: 'pendiente de aprobación',
  visita_agendada: 'visita agendada', presupuesto_enviado: 'presupuesto enviado',
  seguimiento_pendiente: 'seguimiento pendiente', ganada: 'ganada', perdida: 'perdida' };

// Direcciones completas (el iframe de n8n no admite direcciones relativas).
const URL_ABRIR = `${ctx.base}/webhook/llamada`;
const URL_ENVIAR = `${ctx.base}/webhook/llamada-registrar`;
const URL_FICHA = `${ctx.base}/webhook/ficha`;

// ---- 3. Qué se pinta en el cuerpo ---------------------------------------------------
// Tarjeta de aviso o de resultado (tipo: 'ok' verde, 'aviso' naranja, 'error' rojo).
function tarjeta(titulo, mensaje, tipo) {
  return `<section class="tarjeta solo"><div class="aviso ${tipo === 'ok' ? 'verde' : tipo === 'error' ? 'rojo' : ''}">` +
    `<strong class="grande">${esc(titulo)}</strong><br>${esc(mensaje)}</div>` +
    '<p class="suave">Para registrar otra llamada, escribe su número arriba o vuelve al email diario.</p></section>';
}
// Lista de avisos del contexto (ya vienen como texto: se escapan aquí).
const avisosHtml = (ctx.avisos ?? []).map((a) => `<div class="aviso">⚠️ ${esc(a)}</div>`).join('');

let cuerpo = '';          // el contenido bajo la cabecera
let datos = null;         // lo que necesita el JavaScript de la página (solo con formulario)
let subtitulo = 'Escribe el número de oportunidad';

if (ctx.modo === 'buscar') {
  // ---- 3a. Sin número --------------------------------------------------------------
  cuerpo = `<section class="tarjeta solo">${avisosHtml}<p>Escribe arriba el número de oportunidad que aparece en el email diario y pulsa <strong>Abrir</strong>.</p></section>`;
} else if (ctx.modo === 'final') {
  // ---- 3b. Pantalla final ------------------------------------------------------------
  subtitulo = `Oportunidad ${ctx.oportunidad_id}`;
  cuerpo = tarjeta(ctx.final?.titulo ?? 'Aviso', ctx.final?.mensaje ?? '', ctx.final?.tipo ?? 'aviso');
} else {
  // ---- 3c. Modo ficha ---------------------------------------------------------------
  subtitulo = `Oportunidad ${ctx.oportunidad_id}`;
  const b = f?.body ?? {};
  const lr = b.llamada_registrable;                           // null o { tipo_llamada, resultados }
  let vp = null;                                              // la visita pedida (confirmaciones)
  if (!f || f.error) {
    // Sin respuesta del backend.
    tecnicos.push({ nodo: 'leer_ficha_pagina', texto: `Sin respuesta del backend al leer la ficha: ${textoError(f?.error)}` });
    cuerpo = tarjeta('Sistema no disponible', 'No se ha podido conectar con el sistema. Inténtalo de nuevo en unos minutos; el responsable técnico ya ha recibido un aviso.', 'error');
  } else if (f.statusCode === 404) {                          // número que no existe: lo arregla el operador
    cuerpo = tarjeta('No existe', `No existe ninguna oportunidad con el número ${ctx.oportunidad_id}. Revisa el número del email diario.`, 'aviso');
  } else if (f.statusCode === 422) {                          // número mal formado: sin aviso técnico
    cuerpo = tarjeta('Número no válido', 'El número de oportunidad no es válido.', 'aviso');
  } else if (f.statusCode !== 200) {                          // 401, 500, 503...: fallo del sistema -> aviso técnico
    tecnicos.push({ nodo: 'leer_ficha_pagina', texto: `GET /oportunidades/{id}/ficha respondió ${f.statusCode}.` });
    cuerpo = tarjeta('Error del sistema', `Error inesperado del sistema (código ${f.statusCode}). El responsable técnico ya ha recibido un aviso.`, 'error');
  } else if ((b.llamadas ?? []).length > 0 && !b.visita_modificable) {
    // Ya registrada y sin visita que se pueda tocar. Se dice qué y cuándo (nunca el informe).
    const u = b.llamadas[b.llamadas.length - 1];                // la última (vienen de la más antigua a la más reciente)
    const detalle = u.fecha_visita ? `visita el ${fecha(u.fecha_visita)}` : 'sin visita';
    // D46: si la visita se cambió o se canceló después, la fecha de la llamada ya no es la visita (H-D46-2).
    const cv = b.cambios_visita ?? [];                          // los cambios, del más antiguo al más reciente
    const ult = cv.length ? cv[cv.length - 1] : null;           // el último cambio, o null
    const despues = !ult ? ''
      : ult.tipo_cambio === 'cancelar'
        ? ` Después, la visita se canceló el ${fecha(ult.fecha_registro)} y la oportunidad quedó cerrada como perdida.`
        : ` Después, la visita se cambió al ${fecha(ult.fecha_visita_nueva)}.`;
    // Por qué no se puede cambiar ahora (solo si la visita sigue confirmada y ya ha empezado o pasado).
    const pasada = b.estado_oportunidad === 'visita_agendada' && (!ult || ult.tipo_cambio !== 'cancelar') && u.fecha_visita
      ? ' La visita ya ha empezado o ha pasado: no se puede cambiar ni cancelar.' : '';
    cuerpo = tarjeta('Ya está registrada', `La oportunidad ${b.oportunidad_id} ya tiene un resultado (${RESULTADOS[u.resultado] ?? u.resultado}, ${detalle}; registrado el ${fecha(u.fecha_registro)}). Es definitivo: no hace falta volver a registrarlo.${despues}${pasada}`, 'ok');
  } else if (!lr && !b.visita_modificable) {                  // el backend dice que no toca ninguna llamada
    cuerpo = tarjeta('No hay ninguna llamada pendiente', `La oportunidad ${b.oportunidad_id} está en estado "${ESTADOS[b.estado_oportunidad] ?? b.estado_oportunidad}": ahora no toca llamar.`, 'aviso');
  } else if (lr && lr.tipo_llamada === 'confirmacion_visita' && !(b.visitas ?? []).some((x) => x.estado_visita === 'solicitada')) {
    // Incoherencia de datos del sistema: aviso técnico.
    tecnicos.push({ nodo: 'leer_ficha_pagina', texto: 'Confirmación de visita sin visita "solicitada" en la ficha.' });
    cuerpo = tarjeta('No se puede registrar', 'Falta la visita pedida. El responsable técnico ya ha recibido un aviso.', 'error');
  } else {
    // ---- Hay una llamada que registrar, o (D46) una visita confirmada que cambiar: ficha + formulario
    // D46: sin llamada pendiente pero con visita_modificable -> modo visita. La visita actual sale de
    // la ficha (texto recortado, como la visita pedida): es la que se reenvía como fecha_actual + hora_actual.
    const vm = lr ? null : b.visita_modificable;                // { fecha_visita, acciones } o null
    const va = vm ? { fecha: String(vm.fecha_visita).slice(0, 10), hora: String(vm.fecha_visita).slice(11, 16),
      legible: fecha(vm.fecha_visita) } : null;
    if (lr && lr.tipo_llamada === 'confirmacion_visita') {
      const v = b.visitas.find((x) => x.estado_visita === 'solicitada');   // la visita que pidió el cliente
      // Fecha y hora recortadas del texto (ninguna zona horaria las mueve); legible para enseñarla.
      vp = { fecha: String(v.fecha_visita).slice(0, 10), hora: String(v.fecha_visita).slice(11, 16),
             legible: fecha(v.fecha_visita), texto: v.texto_cliente ?? '' };
    }
    // La ficha (columna izquierda). Solo administración: puede ver importes.
    const c = b.contacto ?? {};                                 // nombre, teléfono, origen
    const r = b.reforma ?? {};                                  // tipo, m², acabados
    const p = b.presupuesto;                                    // null si no hay presupuesto
    // Una fila "etiqueta | valor"; el valor SIEMPRE pasa por esc().
    const fila = (et, val) => `<tr><td>${et}</td><td>${esc(val)}</td></tr>`;
    // Contacto de la solicitud, o aviso si la solicitud no lo trae.
    let filas = c.origen === 'solicitud'
      ? fila('Cliente', c.nombre ?? '—') + fila('Teléfono', c.telefono ?? '—')
      : fila('Contacto', 'No disponible en la solicitud: mira la ficha completa');
    // La reforma: tipo, metros y acabado.
    const m2 = r.m2 === null || r.m2 === undefined ? '—' : `${num.format(Number(r.m2))} m²`;
    filas += fila('Reforma', `${TIPOS[r.tipo_reforma] ?? r.tipo_reforma ?? '—'}, ${m2}, acabado ${ACABADOS[r.nivel_acabados] ?? r.nivel_acabados ?? '—'}`);
    if (p) {                                                    // el presupuesto, si existe
      filas += fila('Horquilla (IVA incl.)', `${dinero(p.importe_min_con_iva)} – ${dinero(p.importe_max_con_iva)}`);
      if (p.fecha_presupuesto) {
        const n = diasDesde(p.fecha_presupuesto);                 // días desde el presupuesto (sin reglas: una resta)
        filas += fila('Presupuesto', n <= 0 ? 'hoy' : n === 1 ? 'hace 1 día' : `hace ${n} días`);
      }
    }
    if (vp) filas += fila('Visita pedida', vp.legible);         // en confirmaciones, la hora pedida
    if (va) {                                                   // D46: la visita confirmada y cuántas veces se ha cambiado
      filas += fila('Visita confirmada', va.legible);
      const nCambios = (b.cambios_visita ?? []).filter((x) => x.tipo_cambio === 'cambiar').length;
      if (nCambios > 0) filas += fila('Cambios de hora', nCambios === 1 ? '1 vez' : `${nCambios} veces`);
    }
    // D44: el aviso de última llamada lo decide WF3 (marca ultima=1); aquí no se calcula nada.
    const banner = lr && ctx.ultima === true && lr.tipo_llamada !== 'confirmacion_visita'
      ? '<div class="aviso rojo">⚠️ <strong>Última llamada.</strong> Si sigue sin decidirse, descártalo con el motivo "Sigue sin decidirse (última llamada)".</div>' : '';
    // La etiqueta: el tipo de llamada, o (D46) que es un cambio de una visita ya confirmada.
    const etiqueta = lr ? (TIPOS_LLAMADA[lr.tipo_llamada] ?? lr.tipo_llamada) : 'Visita confirmada: cambiar o cancelar';
    // La tarjeta de la ficha: título, tipo de llamada, aviso, tabla, texto del cliente y enlace.
    const fichaHtml = `<aside class="tarjeta ficha"><div class="titulo-sec">Oportunidad ${esc(b.oportunidad_id)}</div>` +
      `<div class="etiqueta-llamada">${esc(etiqueta)}</div>${banner}` +
      `<table>${filas}</table>` +                                // las filas de arriba
      (vp ? `<div class="suave peq">Lo que dijo el cliente</div><div class="cita">${esc(vp.texto || '—')}</div>` : '') +
      // Enlace a la ficha completa, en una pestaña nueva (dirección completa: el iframe no admite relativas).
      `<a class="enlace" target="_blank" rel="noopener" href="${esc(URL_FICHA)}?oportunidad_id=${esc(b.oportunidad_id)}">Ver ficha completa ↗</a>` +
      '<div class="pie">Uso interno de administración: contiene datos personales.</div></aside>';

    // La agenda: días con horas libres (GET /huecos-libres).
    let dias = [];                                              // los días con horas
    let agendaOk = true;                                        // false si no se pudieron leer
    let avisoAgenda = '';                                       // texto para la agenda (vacío = ninguno)
    if (!rd || rd.error || rd.statusCode !== 200) {
      agendaOk = false;                                         // sin agenda: se puede descartar, no dar visita
      tecnicos.push({ nodo: 'leer_dias', texto: rd?.error ? `Sin respuesta al leer los días libres: ${textoError(rd.error)}` : `GET /huecos-libres respondió ${rd?.statusCode}.` });
      avisoAgenda = 'No se han podido leer las horas libres. Prueba con "Actualizar horas"; el responsable técnico ya ha recibido un aviso.';
    } else {
      // Solo días con fecha AAAA-MM-DD y alguna hora; con título "Lunes 26/10".
      dias = (Array.isArray(rd.body?.dias) ? rd.body.dias : [])
        .filter((d) => d && /^\d{4}-\d{2}-\d{2}$/.test(String(d.fecha ?? '')))
        .map((d) => ({ fecha: d.fecha, titulo: tituloDia(d.dia_semana, d.fecha), manana: horas(d.manana), tarde: horas(d.tarde) }))
        .filter((d) => d.manana.length + d.tarde.length > 0);
      if (dias.length === 0) avisoAgenda = 'No queda ninguna hora libre en los próximos días laborables: usa "Otro día más adelante".';
    }
    // "Otro día más adelante": sus horas, o por qué no hay.
    if (ctx.fecha_extra) {
      if (!rx || rx.error || rx.statusCode !== 200) {
        tecnicos.push({ nodo: 'leer_horas_dia', texto: rx?.error ? `Sin respuesta al leer las horas de un día: ${textoError(rx.error)}` : `GET /huecos-libres?fecha=... respondió ${rx?.statusCode}.` });
        // Aviso en la agenda; lo demás de la pantalla sigue funcionando.
        avisoAgenda = 'No se han podido leer las horas de ese día. Inténtalo de nuevo; el responsable técnico ya ha recibido un aviso.';
      } else {
        // El día pedido, con el mismo formato que los demás (extra = se marca "(otro día)").
        const e = { fecha: String(rx.body?.fecha ?? ctx.fecha_extra), titulo: tituloDia(rx.body?.dia_semana, rx.body?.fecha ?? ctx.fecha_extra),
          manana: horas(rx.body?.manana), tarde: horas(rx.body?.tarde), extra: true };
        // D45: antelacion_insuficiente = ese día es anterior al primero permitido (sin número escrito: lo decide el backend).
        const SIN_HORAS = { dia_completo: 'ya no queda ninguna hora libre', fin_de_semana: 'es fin de semana: no hay visitas', fecha_pasada: 'esa fecha ya ha pasado',
          antelacion_insuficiente: 'es demasiado pronto para una visita (la primera fecha posible es el primer día de la lista)' };
        if (e.manana.length + e.tarde.length === 0) {                // ese día no tiene horas: se dice por qué
          avisoAgenda = `El ${e.titulo.toLowerCase()} ${SIN_HORAS[rx.body?.sin_horas_motivo] ?? 'no tiene ninguna hora libre'}. Elige otro día.`;
        } else if (!dias.some((d) => d.fecha === e.fecha)) {
          dias.push(e);                                  // se añade al final de la lista
        }
      }
    }

    // Lo que necesita el JavaScript de la página (se mete como JSON, nunca como HTML).
    datos = {
      oportunidad_id: b.oportunidad_id,                          // el número
      tipo_llamada: lr ? lr.tipo_llamada : 'cambio_visita',     // gate, seguimiento, confirmacion_visita o (D46) cambio_visita
      // Los botones: los del backend + "No contesta o se lo piensa"; en modo visita (D46), los tres de un cambio.
      resultados: lr ? [...(lr.resultados ?? []), 'sin_registro'] : ['cambiar_visita', 'cancelar_visita', 'sin_cambio'],
      visita_pedida: vp ? { fecha: vp.fecha, hora: vp.hora, legible: vp.legible } : null,
      modo_visita: !!va,                                         // D46: el envío va por el camino de los cambios
      visita_actual: va,                                         // D46: la visita confirmada que ve el operador (o null)
      dias, agenda_ok: agendaOk, aviso_agenda: avisoAgenda,     // la agenda
      fecha_extra: ctx.fecha_extra ?? '',                        // el "otro día" pedido (para Actualizar)
      ultima: ctx.ultima === true ? '1' : ctx.ultima === false ? '0' : '',
      borrador: ctx.borrador ?? {},                              // lo ya escrito (vuelve a ponerse en los campos)
      url_enviar: URL_ENVIAR,                                    // a dónde se envían los formularios
    };
    cuerpo = fichaHtml + `<section class="tarjeta" id="registro">${avisosHtml}${FORMULARIO}</section>`;
  }
}

// ---- 4. La página completa ------------------------------------------------------------
// El JSON de datos va en un <script type="application/json">: el navegador no lo
// ejecuta. "<" se cambia por < para que ningún texto pueda cerrar la etiqueta.
const datosJson = datos ? JSON.stringify(datos).replace(/</g, '\\u003c') : 'null';
// La página: cabecera con la caja del número, el cuerpo, los datos y el JavaScript.
const html = '<!doctype html><html lang="es"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width, initial-scale=1"><title>Registrar llamada</title>' +
  `<style>${CSS}</style></head><body>` +
  '<header class="cab"><h1>Reformas Integrales Amedida · Registrar llamada' +
  `<small>${esc(subtitulo)}</small></h1>` +
  // Caja para escribir el número a mano (D43.7): GET normal, en la ventana entera.
  `<form class="buscar" method="GET" target="_top" action="${esc(URL_ABRIR)}">` +
  '<label for="num">Nº de oportunidad</label>' +
  `<input id="num" name="oportunidad_id" inputmode="numeric" maxlength="10" value="${esc(ctx.oportunidad_id ?? '')}">` +
  '<button type="submit">Abrir</button></form></header><div class="franja"></div>' +
  // El cuerpo (dos columnas con formulario; una sola con avisos).
  `<main class="contenido ${datos ? '' : 'una'}">${cuerpo}</main>` +
  `<script type="application/json" id="datos">${datosJson}</script>` +
  (datos ? `<script>${SCRIPT}</script>` : '') +
  '</body></html>';

// ---- 5. Salida ---------------------------------------------------------------------------
// Un solo aviso técnico por ejecución: se juntan todos los textos (solo códigos y nodos).
return [{
  json: {
    html,                                                       // la página
    codigo: 200,                                                // siempre 200: los avisos van DENTRO de la página
    aviso_tecnico: tecnicos.length > 0,
    nodo_error: tecnicos.map((t) => t.nodo).join(', '),
    mensaje_tecnico: tecnicos.map((t) => t.texto).join(' | '),
    oportunidad_id: ctx.oportunidad_id ?? null,
  },
}];

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Leer lo que envía la pantalla (D43). 2026-10-23.
// Entrada ($json): lo que recibe el Webhook "enviar" (POST, formulario normal de
//   la página). n8n pone los campos en $json.body, todos como TEXTO.
//   accion = 'registrar' -> registrar el resultado de la llamada
//   accion = 'visita'    -> (D46) cambiar o cancelar una visita ya confirmada
//   accion = 'horas'     -> volver a pintar la pantalla con las horas al día
//                           ("Actualizar horas") o con otro día ("Ver sus horas")
// Salida: el CONTEXTO (como validar_apertura) + accion. El borrador guarda lo
//   escrito para volver a ponerlo en la pantalla: así nunca se pierde nada.
// CONFIDENCIAL: el borrador lleva la dirección de la obra. Nunca se copia a un
//   aviso técnico ni a un mensaje de error (D42.5).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Lo que llegó al webhook (una sola petición = un solo elemento).
const w = $input.first().json;
// Los campos del formulario ("?? {}": objeto vacío si no hay cuerpo).
const b = w.body ?? {};
// Las cabeceras (para la dirección pública, igual que en validar_apertura).
const h = w.headers ?? {};

// Un campo como texto, con un tope de longitud: nadie puede colar un texto enorme.
// El tope es MAYOR que el límite real (así el límite real lo dice validar_registro).
function campo(nombre, tope) {
  return String(b[nombre] ?? '').slice(0, tope);
}

// La dirección pública (misma función que validar_apertura).
function baseDe(cab) {
  const host = String(cab['x-forwarded-host'] ?? cab.host ?? '').split(',')[0].trim();   // host público
  const proto = String(cab['x-forwarded-proto'] ?? 'http').split(',')[0].trim();        // protocolo
  if (!/^[A-Za-z0-9.-]+(:[0-9]{1,5})?$/.test(host)) return '';                           // host raro: nada
  if (proto !== 'http' && proto !== 'https') return '';                                  // protocolo raro: nada
  return `${proto}://${host}`;                                                           // "https://dominio"
}

// El número de oportunidad, con la misma regla de siempre.
const texto = campo('oportunidad_id', 20).trim();
const valido = /^[1-9][0-9]{0,9}$/.test(texto);
// La acción: solo tres valores posibles; cualquier otra cosa se trata como "horas" (no escribe nada).
// D46 (2026-10-26): 'visita' = cambiar o cancelar una visita YA confirmada (camino de es_cambio_visita).
const pedida = campo('accion', 20);
const accion = pedida === 'registrar' || pedida === 'visita' ? pedida : 'horas';
// "Otro día más adelante": solo una fecha AAAA-MM-DD; si no, vacío.
const fechaExtra = campo('fecha_extra', 20);

// Lo escrito en la pantalla, tal cual (se valida después, en validar_registro).
const borrador = {
  resultado: campo('resultado', 40),            // el resultado elegido (código)
  fecha: campo('fecha', 20),                    // día elegido en la agenda (AAAA-MM-DD)
  hora: campo('hora', 10),                      // hora elegida (HH:MM)
  calle: campo('calle', 400),                   // dirección de la obra (CONFIDENCIAL)
  cp: campo('cp', 40),
  municipio: campo('municipio', 300),
  motivo: campo('motivo', 40),                  // motivo de descarte o cancelación (código)
  informe: campo('informe', 4000),              // informe de la llamada
  mensaje: campo('mensaje', 1000),              // mensaje para el email del cliente
  // D46: la visita confirmada que VEÍA el operador (fecha AAAA-MM-DD y hora HH:MM); la comprueba el backend.
  fecha_actual: campo('fecha_actual', 20),
  hora_actual: campo('hora_actual', 10),
};

// Sin número válido no se puede seguir: pantalla de búsqueda con un aviso.
const avisos = valido ? [] : ['No llegó un número de oportunidad válido. Escríbelo arriba y pulsa Abrir.'];

return [{
  json: {
    accion,                                       // 'registrar', 'visita' (D46) o 'horas'
    modo: valido ? 'ficha' : 'buscar',            // qué pinta la pantalla
    oportunidad_id: valido ? Number(texto) : null,
    // D44: la marca viaja con la pantalla ('1' sí, '0' no, vacío = no se sabe).
    ultima: campo('ultima', 5) === '1' ? true : campo('ultima', 5) === '0' ? false : null,
    base: baseDe(h),                              // dirección pública para enlaces y formularios
    // "Otro día más adelante": solo una fecha con forma AAAA-MM-DD.
    fecha_extra: /^\d{4}-\d{2}-\d{2}$/.test(fechaExtra) ? fechaExtra : '',
    borrador,                                     // lo escrito, para volver a ponerlo
    avisos,                                       // avisos para la pantalla
    final: null,                                  // todavía no hay pantalla final
    aviso_tecnico: false,                         // nada que avisar al técnico todavía
    nodo_error: '',
    mensaje_tecnico: '',
  },
}];

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Comprobar lo enviado ANTES de registrar (D43). 2026-10-23.
// Basado en preparar_ficha y preparar_decision del formulario viejo (ya probados).
// Entrada:
//   $json                        -> la ficha recién leída (leer_ficha_registro):
//                                   { statusCode, body } o { error } si no hubo respuesta
//   $('preparar_envio')          -> el contexto y lo escrito (borrador)
// Salida (1 elemento):
//   valido = true  -> { valido, cuerpo, mensaje_cliente, nombre, tipo_reforma, ...contexto }
//                     cuerpo = el JSON EXACTO para POST /resultados-llamada
//   valido = false -> el CONTEXTO para volver a pintar la pantalla (con el aviso)
//                     o para la pantalla final (modo 'final')
// La ficha se vuelve a leer AQUÍ, en el servidor: la hora pedida, los resultados
// admitidos y el tipo de llamada NUNCA se toman de lo que manda el navegador.
// CONFIDENCIAL: ningún aviso ni mensaje copia la dirección ni el informe (D42.5).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// El contexto y lo escrito en la pantalla.
const env = $('preparar_envio').first().json;
const d = env.borrador ?? {};
// La ficha leída ahora mismo.
const f = $input.first().json;
const b = f.body ?? {};

// El contexto base, para las salidas que vuelven a pintar la pantalla.
function contexto(extra) {
  return {
    valido: false,                               // registro_valido manda esto a "contexto"
    modo: 'ficha', oportunidad_id: env.oportunidad_id, ultima: env.ultima, base: env.base,
    fecha_extra: env.fecha_extra, borrador: d, avisos: [], final: null,
    aviso_tecnico: false, nodo_error: '', mensaje_tecnico: '',
    ...extra,                                    // lo que cambie en cada caso
  };
}
// Pantalla final de aviso (no hay nada que corregir en la pantalla).
function final(titulo, mensaje, tecnico = false, mensaje_tecnico = '') {
  return [{ json: contexto({ modo: 'final', final: { titulo, mensaje, tipo: 'aviso' },
    aviso_tecnico: tecnico, nodo_error: tecnico ? 'leer_ficha_registro' : '', mensaje_tecnico }) }];
}
// Volver a la pantalla con uno o varios avisos (lo escrito se conserva).
function corregir(...avisos) {
  return [{ json: contexto({ avisos }) }];
}
const NADA = ' No se ha registrado nada.';

// ---- 1. La ficha: ¿se puede registrar? (como preparar_ficha) -----------------
if (f.error) {
  // Sin respuesta del backend: nada que hacer; aviso técnico (solo el código del error).
  const e = f.error;                                       // el error de n8n
  const detalle = typeof e === 'string' ? e : [e.code, e.message].filter((x) => typeof x === 'string').join(' · ');
  return final('Sistema no disponible', 'No se ha podido conectar con el sistema.' + NADA +
    ' Inténtalo de nuevo en unos minutos.', true, `Sin respuesta al leer la ficha antes de registrar: ${detalle || 'sin detalle'}`);
}
// 404 y 422: los arregla el operador (sin aviso técnico).
if (f.statusCode === 404) return final('No se puede registrar', 'No existe ninguna oportunidad con ese número.' + NADA);
if (f.statusCode === 422) return final('No se puede registrar', 'El número de oportunidad no es válido.' + NADA);
if (f.statusCode !== 200) {
  // 401, 500, 503...: fallo del sistema -> aviso técnico.
  return final('Error del sistema', `Error inesperado del sistema (código ${f.statusCode}).` + NADA +
    ' El responsable técnico ya ha recibido un aviso.', true, `GET /oportunidades/{id}/ficha respondió ${f.statusCode} antes de registrar.`);
}
// Ya tiene un resultado (es definitivo).
if ((b.llamadas ?? []).length > 0) {
  return final('Ya está registrada', `La oportunidad ${b.oportunidad_id} ya tiene un resultado registrado. Es definitivo: no hace falta volver a registrarlo.`);
}
// Nada pendiente.
const lr = b.llamada_registrable;                  // null o { tipo_llamada, resultados }
if (!lr) return final('No hay ninguna llamada pendiente', `La oportunidad ${b.oportunidad_id} no tiene ninguna llamada pendiente.` + NADA);
// En una confirmación, la hora PEDIDA sale de la ficha (texto recortado, sin zonas horarias).
let vp = null;
if (lr.tipo_llamada === 'confirmacion_visita') {
  const v = (b.visitas ?? []).find((x) => x.estado_visita === 'solicitada');
  if (!v) return final('No se puede registrar', 'Falta la visita pedida.' + NADA + ' El responsable técnico ya ha recibido un aviso.',
    true, 'Confirmación de visita sin visita "solicitada" en la ficha.');
  // Fecha y hora recortadas del texto ("2026-10-27T10:30:00+01:00" -> "2026-10-27" y "10:30").
  vp = { fecha: String(v.fecha_visita).slice(0, 10), hora: String(v.fecha_visita).slice(11, 16) };
}

// ---- 2. Lo escrito: las mismas reglas que el backend ------------------------
// Texto con el carácter nulo: psycopg2 lo rechaza con un 500 (H-D42-1). Se para aquí.
const tieneNulo = (t) => t.includes('\u0000');
const resultado = String(d.resultado ?? '');
// El resultado tiene que estar entre los que el backend admite para ESTA llamada.
if (!(lr.resultados ?? []).includes(resultado)) {
  return corregir('La situación de esta oportunidad ha cambiado o el resultado no es válido: revisa la pantalla y vuelve a elegir.');
}
// El informe: sin espacios sobrantes, de 1 a 2.000 caracteres (lo mismo que exige el backend).
const informe = String(d.informe ?? '').trim();
if (informe.length === 0) return corregir('El informe de la llamada está vacío.');
if (informe.length > 2000) return corregir(`El informe tiene ${informe.length} caracteres; el máximo es 2.000.`);
if (tieneNulo(informe)) return corregir('El informe contiene un carácter no válido. Vuelve a escribirlo.');

// ¿Queda una visita? Entonces hacen falta la dirección y (opcional) el mensaje.
const conVisita = ['visita_acordada', 'confirmar_hora', 'otra_hora'].includes(resultado);
const cuerpo = { oportunidad_id: b.oportunidad_id, resultado, informe };
let mensaje_cliente = '';
if (conVisita) {
  // Día y hora: elegidos en la agenda; en "confirmar_hora", los de la ficha.
  if (resultado === 'confirmar_hora') {
    cuerpo.fecha = vp.fecha; cuerpo.hora = vp.hora;      // la hora pedida, de la ficha
  } else {
    const fecha = String(d.fecha ?? ''), hora = String(d.hora ?? '');   // las elegidas en la agenda
    if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !/^\d{2}:\d{2}$/.test(hora)) return corregir('Falta el día o la hora de la visita.');
    // "Otra hora" no puede ser la misma que pidió el cliente (el backend daría 422).
    if (resultado === 'otra_hora' && vp && fecha === vp.fecha && hora === vp.hora) {
      return corregir('Es la misma hora que pidió el cliente: elige "Confirmar la hora pedida".');
    }
    cuerpo.fecha = fecha; cuerpo.hora = hora;
  }
  // La dirección de la obra (D42.3): los mismos límites que el backend.
  const calle = String(d.calle ?? '').trim();              // los tres campos, sin espacios sobrantes
  const cp = String(d.cp ?? '').trim();
  const municipio = String(d.municipio ?? '').trim();
  const errores = [];                                      // se juntan todos los errores para decirlos a la vez
  if (calle.length < 1 || calle.length > 150) errores.push('La calle y número tiene que tener entre 1 y 150 caracteres.');
  if (!/^(0[1-9]|[1-4][0-9]|5[0-2])[0-9]{3}$/.test(cp)) errores.push('El código postal no es válido.');
  if (municipio.length < 1 || municipio.length > 100) errores.push('El municipio tiene que tener entre 1 y 100 caracteres.');
  // Carácter nulo en cualquiera de los tres (H-D42-1).
  if ([calle, cp, municipio].some(tieneNulo)) errores.push('La dirección contiene un carácter no válido.');
  if (errores.length) return corregir(...errores);
  // Todo bien: la dirección va en el cuerpo, ya recortada.
  cuerpo.direccion_obra = { calle_numero: calle, codigo_postal: cp, municipio };
  // El mensaje para el cliente (D39.4): opcional, máx. 500, va al email (WF7), NUNCA al backend.
  mensaje_cliente = String(d.mensaje ?? '').trim();
  if (mensaje_cliente.length > 500) return corregir(`El mensaje para el cliente tiene ${mensaje_cliente.length} caracteres; el máximo es 500.`);
  if (tieneNulo(mensaje_cliente)) return corregir('El mensaje para el cliente contiene un carácter no válido.');
} else {
  // descartar o cliente_cancela: motivo OBLIGATORIO (códigos del backend, D29.3).
  const MOTIVOS = ['precio', 'plazo', 'no_contesta', 'sin_decision', 'proyecto_no_viable', 'otro'];
  const motivo = String(d.motivo ?? '');
  if (!MOTIVOS.includes(motivo)) return corregir('Elige el motivo.');
  // Quien cancela ha contestado y ha decidido: esos dos motivos no valen.
  if (resultado === 'cliente_cancela' && (motivo === 'no_contesta' || motivo === 'sin_decision')) {
    return corregir('Ese motivo no vale cuando el cliente cancela. Elige otro.');
  }
  cuerpo.motivo = motivo;
}

// ---- 3. Todo listo -------------------------------------------------------------
const c = b.contacto ?? {};
return [{
  json: {
    ...contexto({}),
    valido: true,
    cuerpo,                                       // para POST /resultados-llamada
    mensaje_cliente,                              // para WF7 (vacío sin visita)
    nombre: c.origen === 'solicitud' ? (c.nombre ?? '') : '',   // título del evento (WF5): solo el nombre
    tipo_reforma: b.reforma?.tipo_reforma ?? '',  // título del evento (WF5)
  },
}];

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Traducir la respuesta de POST /resultados-llamada (D43).
// 2026-10-23. Basado en traducir_resultado del formulario viejo (ya probado), con
// una mejora: los errores que se arreglan ELIGIENDO OTRA COSA vuelven a la
// pantalla con todo lo escrito, en vez de obligar a empezar de nuevo (H-D42-3).
// Entrada ($json): { statusCode, body } o { error } si se cortó la conexión.
// Salida (1 elemento), con destino:
//   'calendario' -> registrado (201 o 200): sigue a preparar_calendario
//   'pantalla'   -> no registrado y se puede corregir: el CONTEXTO, modo 'ficha'
//   'final'      -> no registrado y no hay nada que corregir: el CONTEXTO, modo 'final'
// Textos: secciones 4 y 4b de docs/Contrato_Formulario_Llamadas.md.
// D45 (23/10, noche): 422 antelacion_insuficiente = error del operador (elegir otro día), NUNCA técnico.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// La respuesta del backend.
const r = $input.first().json;
const estado = r.statusCode;
const b = r.body ?? {};
// Lo que se envió y el contexto de la pantalla.
const v = $('validar_registro').first().json;
const enviado = v.cuerpo ?? {};
const op = enviado.oportunidad_id;
const NADA = ' No se ha registrado nada.';

// Fecha y hora en español y hora de Madrid, solo para MOSTRAR.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit',
    year: 'numeric', hour: '2-digit', minute: '2-digit',
  });
}
// "2026-10-26" -> "26/10/2026" (sin zonas horarias: se recorta el texto).
const diaCorto = (f) => (/^\d{4}-\d{2}-\d{2}$/.test(String(f)) ? `${f.slice(8, 10)}/${f.slice(5, 7)}/${f.slice(0, 4)}` : '');
// Motivos del backend -> texto para administración.
const MOTIVOS = { precio: 'precio', plazo: 'plazo', no_contesta: 'no contesta', proyecto_no_viable: 'proyecto no viable',
  otro: 'otro', sin_decision: 'sigue sin decidirse' };

// El contexto común (sin cuerpo ni datos de registro: solo lo de la pantalla).
function ctx(extra) {
  return { destino: 'pantalla', modo: 'ficha', oportunidad_id: v.oportunidad_id, ultima: v.ultima, base: v.base,
    fecha_extra: v.fecha_extra, borrador: v.borrador, avisos: [], final: null,
    aviso_tecnico: false, nodo_error: '', mensaje_tecnico: '', ...extra };
}
// Volver a la pantalla con un aviso. limpiarHora: la hora elegida ya no vale.
function pantalla(aviso, limpiarHora = false, tecnico = false, mensaje_tecnico = '') {
  const borrador = limpiarHora ? { ...v.borrador, fecha: '', hora: '' } : v.borrador;
  return [{ json: ctx({ avisos: [aviso], borrador, aviso_tecnico: tecnico,
    nodo_error: tecnico ? 'registrar_resultado' : '', mensaje_tecnico }) }];
}
// Pantalla final (tipo 'ok' = verde; 'aviso' = naranja).
function final(titulo, mensaje, tipo = 'aviso', tecnico = false, mensaje_tecnico = '') {
  return [{ json: ctx({ destino: tipo === 'ok' ? 'calendario' : 'final', modo: 'final',
    final: { titulo, mensaje, tipo }, aviso_tecnico: tecnico,
    nodo_error: tecnico ? 'registrar_resultado' : '', mensaje_tecnico }) }];
}

// ---- 0. Sin respuesta: puede que se haya registrado o no ---------------------
if (r.error) {
  const e = r.error;
  const detalle = typeof e === 'string' ? e : [e.code, e.message].filter((x) => typeof x === 'string').join(' · ');
  return final('No se sabe si se ha registrado',
    'Se ha perdido la conexión con el sistema durante el registro. Vuelve a abrir la pantalla con el mismo número: ' +
    'si se registró, lo verás indicado; si no, podrás registrarlo de nuevo sin riesgo de duplicarlo.',
    'aviso', true, `Sin respuesta durante POST /resultados-llamada; NO se sabe si se registró: ${detalle || 'sin detalle'}`);
}

// ---- 1. Éxito: 201 (registrado ahora) o 200 (repetición exacta) -------------
if (estado === 201 || estado === 200) {
  // 200: el backend no ha escrito nada (repetición exacta; normal si se reintenta).
  if (estado === 200) return final('Ya estaba registrado', `Oportunidad ${op}: este mismo resultado ya estaba registrado. No se ha cambiado nada.`, 'ok');
  if (['visita_acordada', 'confirmar_hora', 'otra_hora'].includes(b.resultado)) {
    // Con visita (acordada, hora confirmada u otra hora); en "otra hora", la pedida queda cancelada.
    const cancelada = b.resultado === 'otra_hora' ? ' La hora que había pedido el cliente queda cancelada.' : '';
    return final('Visita registrada', `Oportunidad ${op}: visita confirmada el ${fecha(b.fecha_visita)}.${cancelada}`, 'ok');
  }
  if (b.resultado === 'descartar') {                       // descarte: la oportunidad queda perdida
    return final('Descarte registrado', `Oportunidad ${op} descartada, motivo: ${MOTIVOS[b.motivo] ?? b.motivo}. La oportunidad queda cerrada como perdida.`, 'ok');
  }
  if (b.resultado === 'cliente_cancela') {                 // cancelación del cliente
    return final('Cancelación registrada', `Oportunidad ${op}: el cliente cancela, motivo: ${MOTIVOS[b.motivo] ?? b.motivo}. ` +
      'La visita pedida queda cancelada y la oportunidad cerrada como perdida.', 'ok');
  }
  // Un resultado nuevo que este nodo no conoce: se enseña tal cual.
  return final('Resultado registrado', `Oportunidad ${op}: ${b.resultado}.`, 'ok');
}

// ---- 2. Errores que se corrigen en la pantalla (todo lo escrito se conserva) --
const motivo = b.detail?.motivo;                          // el motivo del error que da el backend
const mensajeBackend = String(b.detail?.mensaje ?? '');
if (estado === 409 && motivo === 'hueco_ocupado') {
  if (enviado.resultado === 'visita_acordada' || enviado.resultado === 'otra_hora') {
    return pantalla(`La hora ${enviado.hora} del ${diaCorto(enviado.fecha)} se acaba de ocupar.${NADA} Elige otra con el cliente; lo demás sigue escrito.`, true);
  }
  // confirmar_hora: la hora pedida ya no está libre -> elegir "Otra hora".
  return pantalla(`La hora que pidió el cliente ya está ocupada por otra visita.${NADA} Elige "Otra hora" y acuerda una nueva con él.`);
}
// D45: antelacion_insuficiente también (por ejemplo, la pantalla se abrió antes de medianoche y se envió después).
if (estado === 422 && ['fecha_pasada', 'fin_de_semana', 'fuera_de_franja', 'antelacion_insuficiente'].includes(motivo)) {
  return pantalla(`${mensajeBackend}${NADA} Elige otro día u otra hora.`, true);
}
if (estado === 422 && motivo === 'fuera_de_rejilla') {
  // No debería pasar nunca (las horas salen de /huecos-libres): fallo de la pantalla -> aviso técnico.
  return pantalla(`Esa hora no es válida.${NADA} Elige otra; el responsable técnico ya ha recibido un aviso.`, true, true,
    'POST /resultados-llamada respondió 422 fuera_de_rejilla: la pantalla ofreció una hora fuera de la rejilla.');
}
if (estado === 422 && motivo === 'misma_hora_pedida') {
  return pantalla(`Es la hora que pidió el cliente: elige "Confirmar la hora pedida".${NADA}`, true);
}
if (estado === 409 && (motivo === 'resultado_no_admitido' || motivo === 'visita_cambiada')) {
  // La situación cambió desde que se abrió la pantalla: se vuelve a pintar CON LA FICHA NUEVA.
  const texto = motivo === 'visita_cambiada' ? 'El cliente ha cambiado la hora pedida mientras tanto.' : 'La situación del cliente ha cambiado mientras tanto.';
  return pantalla(`${texto}${NADA} Revisa la pantalla, que ya está al día, y vuelve a elegir.`, true);
}

// ---- 3. Errores sin nada que corregir: pantalla final -------------------------
const MENSAJES = {
  resultado_ya_registrado: 'Esta llamada ya tiene un resultado registrado (es definitivo).',
  estado_no_permitido: 'Esta oportunidad no tiene ninguna llamada pendiente.',
  sin_presupuesto: 'Todavía no tiene presupuesto.',
  visita_activa_existente: 'Ya tiene una visita activa.',
  oportunidad_no_encontrada: 'Oportunidad no encontrada.',
};
if (MENSAJES[motivo]) return final('No se ha podido registrar', MENSAJES[motivo] + NADA);
if (['plazo_no_cumplido', 'contacto_registrado', 'visita_existente', 'con_gate'].includes(motivo)) {
  return final('No se ha podido registrar', `Esta oportunidad no está en el seguimiento ahora mismo.${NADA}`);
}
// Errores técnicos: aviso al responsable técnico (solo códigos, nunca el cuerpo enviado).
const TECNICOS = { 401: 'Error de configuración', 422: 'Error en los datos enviados', 503: 'Sistema no disponible' };
return final(TECNICOS[estado] ?? 'Error inesperado', `El sistema no ha aceptado el registro (código ${estado}).${NADA} ` +
  'El responsable técnico ya ha recibido un aviso.', 'aviso', true,
  `POST /resultados-llamada respondió ${estado}${motivo ? ` (${motivo})` : ''}.`);

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Preparar las llamadas a WF5 (D33, D43). 2026-10-23.
// Copia de preparar_calendario del formulario viejo (ya probado); solo cambia de
// dónde salen el nombre y el tipo de reforma (validar_registro, en vez de preparar_ficha).
// Lo decide la RESPUESTA del backend, no el resultado elegido:
//   visita_cancelada_id  -> WF5 'borrar' esa visita   (otra_hora, cliente_cancela)
//   visita_id            -> WF5 'guardar' confirmada  (visita_acordada, confirmar_hora, otra_hora)
// También en un 200 (repetición): WF5 no duplica nunca, y así se recupera un
// calendario que falló la primera vez.
// Salida: 1 elemento por llamada a WF5, o 1 elemento { sin_calendario: true }.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// La respuesta del registro.
const resp = $('registrar_resultado').first().json;
const estado = resp.statusCode;                       // 201, 200...
const b = resp.body ?? {};                            // el cuerpo ("?? {}": vacío si no hay)
// Nombre y tipo de reforma, leídos de la ficha en validar_registro.
const v = $('validar_registro').first().json;

// Sin registro (no debería llegar aquí): nada que copiar.
if (estado !== 201 && estado !== 200) return [{ json: { sin_calendario: true } }];

// Lo común a todas las llamadas (RGPD: solo el nombre, nunca el contacto ni la dirección).
const comun = {
  nombre: v.nombre ?? '',
  tipo_reforma: v.tipo_reforma ?? '',
  oportunidad_id: b.oportunidad_id ?? v.oportunidad_id,
};

const llamadas = [];                                  // las llamadas a WF5, en orden
// 1. La visita pedida que se ha cancelado: su evento amarillo se borra.
if (b.visita_cancelada_id) {
  llamadas.push({ accion: 'borrar', visita_id: b.visita_cancelada_id, estado_visita: '', inicio: '', fin: '', ...comun });
}
// 2. La visita que queda confirmada: se crea, o se pasa de amarillo a verde.
//    Inicio y fin, tal cual los da el backend (n8n no suma la duración, D33).
if (b.visita_id) {
  llamadas.push({ accion: 'guardar', visita_id: b.visita_id, estado_visita: 'confirmada',
    inicio: b.fecha_visita ?? '', fin: b.fecha_fin_visita ?? '', ...comun });
}

// Descartar (sin visitas): nada que copiar.
if (llamadas.length === 0) return [{ json: { sin_calendario: true } }];
// Un elemento por llamada: llamar_calendario (modo "each") llama a WF5 una vez por cada uno.
return llamadas.map((j) => ({ json: j }));

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Texto de la pantalla final (D33, D43). 2026-10-23.
// Basado en cerrar_pantalla del formulario viejo (ya probado, F-1 incluido).
// Recibe de dos sitios (se sabe cuál con $prevNode.name):
//   - necesita_calendario -> no había nada que copiar (descarte): el texto tal cual
//   - llamar_calendario   -> 1 resultado de WF5 por llamada: { ok, ... }, o { error }
//                            si WF5 no se pudo ni ejecutar
// Salida: el CONTEXTO en modo 'final' para construir_pagina.
//   aviso_tecnico = true SOLO si WF5 no se ejecutó (si se ejecutó y falló, ya avisó él).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// El contexto y el texto del registro (traducir_resultado).
const t = $('traducir_resultado').first().json;
// Lo que se envió (para saber el resultado) y la respuesta (para saber si sale el email).
const v = $('validar_registro').first().json;
const resp = $('registrar_resultado').first().json;
// ¿Sale el email de "visita confirmada"? La MISMA condición que el nodo email_visita.
const saleEmail = resp.statusCode === 201 && ['visita_acordada', 'confirmar_hora', 'otra_hora'].includes(resp.body?.resultado)
  && !!resp.body?.visita_id;
const lineaEmail = saleEmail ? ' Se envía al cliente un email con la confirmación de la visita.' : '';

// Atajo para la salida: el contexto de traducir_resultado con su pantalla final.
function salida(titulo, mensaje, tipo, tecnico = false, mensaje_tecnico = '') {
  return [{ json: { ...t, modo: 'final', final: { titulo, mensaje, tipo },
    aviso_tecnico: tecnico, nodo_error: tecnico ? 'llamar_calendario' : '', mensaje_tecnico } }];
}

// Sin calendario (descarte): el texto de siempre.
if ($prevNode.name !== 'llamar_calendario') return salida(t.final.titulo, t.final.mensaje, 'ok');

// ¿Se confirma la hora que pidió el cliente? Entonces su evento pendiente ya existía (F-1).
const esConfirmarHora = String(v.cuerpo?.resultado ?? '') === 'confirmar_hora';
// Lo que se pidió a WF5 y lo que contestó, en el mismo orden.
const pedidas = $('preparar_calendario').all().map((i) => i.json);
const resultados = $input.all().map((i) => i.json);
const hayGuardar = pedidas.some((p) => p.accion === 'guardar');

// Texto de un error de n8n sin enviar el objeto entero (podría llevar datos).
function textoError(e) {
  if (!e) return 'sin detalle';                                  // no llegó nada
  if (typeof e === 'string') return e;                           // ya es un texto
  const partes = [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '');
  return partes.length > 0 ? partes.join(' · ') : 'error sin texto';
}

// Fallo de la LLAMADA (WF5 no llegó a ejecutarse) o fallo DENTRO de WF5 (ok = false; ya avisó él).
const falloLlamada = resultados.length !== pedidas.length || resultados.some((r) => typeof r.ok !== 'boolean');
const falloWf5 = resultados.some((r) => r.ok === false);
if (falloLlamada || falloWf5) {
  // El registro SÍ está hecho: que nadie lo repita, y que se sepa que el calendario no cuadra.
  const titulo = hayGuardar ? 'Visita registrada, pero NO copiada al calendario' : 'Registrado, pero el calendario no se ha actualizado';
  const mensaje = `${t.final.mensaje}${lineaEmail} ⚠️ El registro SÍ está guardado: no lo repitas. ` +
    'No se ha podido actualizar el calendario "Visitas técnicas — Reformas Amedida": el responsable técnico ya ha recibido un aviso.';
  // Solo si WF5 no se ejecutó hace falta que este flujo avise (si no, WF4 llegaría dos veces).
  const tecnico = falloLlamada
    ? `WF5 no se pudo ejecutar (${resultados.length} de ${pedidas.length} respuestas): ` + resultados.map((r) => textoError(r.error)).join(' | ')
    : '';
  return salida(titulo, mensaje, 'aviso', falloLlamada, tecnico);
}

// Todo bien: el título y la frase del calendario según el caso.
let titulo = t.final.titulo;
if (resp.statusCode === 201 && hayGuardar) {
  titulo = esConfirmarHora ? 'Visita registrada y actualizada en el calendario' : 'Visita registrada y añadida al calendario';
}
let frase;                                                       // la frase del calendario
// Otra hora (borrar + guardar), confirmar la hora pedida, visita nueva o solo borrar (cancela).
if (hayGuardar && pedidas.length > 1) frase = ' Calendario actualizado: la hora anterior se ha quitado y la nueva está añadida.';
else if (hayGuardar && esConfirmarHora) frase = ' Calendario actualizado: la visita pedida ya figura como confirmada.';
else if (hayGuardar) frase = ' Visita añadida al calendario "Visitas técnicas — Reformas Amedida".';
else frase = ' La visita pedida se ha quitado del calendario.';
// Pantalla final verde: el texto del registro + la frase del calendario + la del email.
return salida(titulo, t.final.mensaje + frase + lineaEmail, 'ok');

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Comprobar un cambio de visita ANTES de enviarlo (D46). 2026-10-26.
// Mismo patrón que validar_registro (ya probado), para POST /cambios-visita.
// Entrada:
//   $json                        -> la ficha recién leída (leer_ficha_cambio):
//                                   { statusCode, body } o { error } si no hubo respuesta
//   $('preparar_envio')          -> el contexto y lo escrito (borrador)
// Salida (1 elemento):
//   valido = true  -> { valido, cuerpo, mensaje_cliente, nombre, tipo_reforma, ...contexto }
//                     cuerpo = el JSON EXACTO para POST /cambios-visita
//   valido = false -> el CONTEXTO para volver a pintar la pantalla (con el aviso)
//                     o para la pantalla final (modo 'final')
// La fecha y hora ACTUALES son las que vio el operador (borrador): si alguien cambió la
// visita mientras tanto, se le dice aquí y, si no, lo dice el backend (409 visita_cambiada).
// CONFIDENCIAL: ningún aviso ni mensaje copia el informe (D42.5).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// El contexto y lo escrito en la pantalla.
const env = $('preparar_envio').first().json;
const d = env.borrador ?? {};
// La ficha leída ahora mismo.
const f = $input.first().json;
const b = f.body ?? {};

// El contexto base, para las salidas que vuelven a pintar la pantalla.
function contexto(extra) {
  return {
    valido: false,                               // cambio_valido manda esto a vuelta_cambio
    modo: 'ficha', oportunidad_id: env.oportunidad_id, ultima: env.ultima, base: env.base,
    fecha_extra: env.fecha_extra, borrador: d, avisos: [], final: null,
    aviso_tecnico: false, nodo_error: '', mensaje_tecnico: '',
    ...extra,                                    // lo que cambie en cada caso
  };
}
// Pantalla final de aviso (no hay nada que corregir en la pantalla).
function final(titulo, mensaje, tecnico = false, mensaje_tecnico = '') {
  return [{ json: contexto({ modo: 'final', final: { titulo, mensaje, tipo: 'aviso' },
    aviso_tecnico: tecnico, nodo_error: tecnico ? 'leer_ficha_cambio' : '', mensaje_tecnico }) }];
}
// Volver a la pantalla con uno o varios avisos (lo escrito se conserva).
function corregir(...avisos) {
  return [{ json: contexto({ avisos }) }];
}
const NADA = ' No se ha cambiado nada.';

// ---- 1. La ficha: ¿hay una visita que se pueda cambiar? ------------------------
if (f.error) {
  // Sin respuesta del backend: nada que hacer; aviso técnico (solo el código del error).
  const e = f.error;                                       // el error de n8n
  const detalle = typeof e === 'string' ? e : [e.code, e.message].filter((x) => typeof x === 'string').join(' · ');
  return final('Sistema no disponible', 'No se ha podido conectar con el sistema.' + NADA +
    ' Inténtalo de nuevo en unos minutos.', true, `Sin respuesta al leer la ficha antes de cambiar la visita: ${detalle || 'sin detalle'}`);
}
// 404 y 422: los arregla el operador (sin aviso técnico).
if (f.statusCode === 404) return final('No se puede cambiar', 'No existe ninguna oportunidad con ese número.' + NADA);
if (f.statusCode === 422) return final('No se puede cambiar', 'El número de oportunidad no es válido.' + NADA);
if (f.statusCode !== 200) {
  // 401, 500, 503...: fallo del sistema -> aviso técnico.
  return final('Error del sistema', `Error inesperado del sistema (código ${f.statusCode}).` + NADA +
    ' El responsable técnico ya ha recibido un aviso.', true, `GET /oportunidades/{id}/ficha respondió ${f.statusCode} antes de cambiar la visita.`);
}
// ---- 2. Lo escrito: las mismas reglas que el backend ------------------------
// Texto con el carácter nulo: el backend lo rechaza con 422 (H-D46-6). Se para aquí, con un texto claro.
const tieneNulo = (t) => t.includes('\u0000');
const resultado = String(d.resultado ?? '');
// Solo las dos acciones de un cambio.
if (resultado !== 'cambiar_visita' && resultado !== 'cancelar_visita') {
  return corregir('Elige qué hacer con la visita: cambiar el día o la hora, o cancelarla.');
}
// La visita que veía el operador: fecha AAAA-MM-DD y hora HH:MM.
const fechaActual = String(d.fecha_actual ?? ''), horaActual = String(d.hora_actual ?? '');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaActual) || !/^\d{2}:\d{2}$/.test(horaActual)) {
  return corregir('La pantalla no traía la visita actual. Revisa la pantalla, que ya está al día, y vuelve a elegir.');
}
// Fecha y hora de un texto ISO de la ficha, recortadas como en la pantalla ("2026-11-03T09:45:00+01:00").
const fh = (t) => ({ fecha: String(t ?? '').slice(0, 10), hora: String(t ?? '').slice(11, 16) });
// ¿Es la REPETICIÓN del último cambio (página recargada o enviada dos veces)? Entonces se manda
// igual: el backend responde 200 sin escribir nada y WF5 deja el calendario como debe estar.
const cv = b.cambios_visita ?? [];                          // los cambios, del más antiguo al más reciente
const ult = cv.length ? cv[cv.length - 1] : null;           // el último, o null
const ultAnterior = fh(ult?.fecha_visita_anterior), ultNueva = fh(ult?.fecha_visita_nueva);
const repetido = !!ult && ultAnterior.fecha === fechaActual && ultAnterior.hora === horaActual && (
  resultado === 'cambiar_visita'
    ? ult.tipo_cambio === 'cambiar' && ultNueva.fecha === String(d.fecha ?? '') && ultNueva.hora === String(d.hora ?? '')
    : ult.tipo_cambio === 'cancelar' && ult.motivo === String(d.motivo ?? ''));
// La visita que se puede tocar (la MISMA regla que el backend): null si ya no hay ninguna.
const vm = b.visita_modificable;
if (!vm && !repetido) {
  // ¿Por qué? Si el último cambio fue una cancelación, se dice; si no, ya pasó o no hay visita confirmada.
  const cancelada = ult?.tipo_cambio === 'cancelar';
  return final('No se puede cambiar', (cancelada
    ? 'Esta visita ya se canceló (la oportunidad está cerrada como perdida).'
    : 'La oportunidad ya no tiene ninguna visita confirmada que se pueda cambiar (o la visita ya ha empezado o pasado).') + NADA);
}
// La de la ficha ahora mismo. Si no es la que veía el operador (y no es una repetición), otra persona la cambió.
if (vm && !repetido) {
  const ahora = fh(vm.fecha_visita);
  if (ahora.fecha !== fechaActual || ahora.hora !== horaActual) {
    return corregir('La visita ha cambiado mientras tanto (otra persona la ha modificado).' + NADA +
      ' Revisa la pantalla, que ya está al día, y vuelve a elegir.');
  }
}
// El informe: sin espacios sobrantes, de 1 a 2.000 caracteres (lo mismo que exige el backend).
const informe = String(d.informe ?? '').trim();
if (informe.length === 0) return corregir('El informe de la llamada está vacío.');
if (informe.length > 2000) return corregir(`El informe tiene ${informe.length} caracteres; el máximo es 2.000.`);
if (tieneNulo(informe)) return corregir('El informe contiene un carácter no válido. Vuelve a escribirlo.');

// El cuerpo para POST /cambios-visita (nombres del Contrato, sección 4c).
const cuerpo = { oportunidad_id: b.oportunidad_id, accion: resultado === 'cambiar_visita' ? 'cambiar' : 'cancelar',
  fecha_actual: fechaActual, hora_actual: horaActual, informe };
let mensaje_cliente = '';
if (cuerpo.accion === 'cambiar') {
  // La nueva fecha y hora, elegidas en la agenda.
  const fecha = String(d.fecha ?? ''), hora = String(d.hora ?? '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !/^\d{2}:\d{2}$/.test(hora)) return corregir('Falta el nuevo día o la nueva hora.');
  // La misma hora que ya tiene: el backend daría 422 misma_hora_actual.
  if (fecha === fechaActual && hora === horaActual) return corregir('Es la misma hora que ya tiene: elige otra.');
  cuerpo.fecha = fecha; cuerpo.hora = hora;
  // El mensaje para el cliente (D39.4): opcional, máx. 500, va al email (WF7), NUNCA al backend.
  mensaje_cliente = String(d.mensaje ?? '').trim();
  if (mensaje_cliente.length > 500) return corregir(`El mensaje para el cliente tiene ${mensaje_cliente.length} caracteres; el máximo es 500.`);
  if (tieneNulo(mensaje_cliente)) return corregir('El mensaje para el cliente contiene un carácter no válido.');
} else {
  // Cancelar: motivo OBLIGATORIO, los cuatro de "el cliente cancela" (D46.3: ni no_contesta ni sin_decision).
  const MOTIVOS = ['precio', 'plazo', 'proyecto_no_viable', 'otro'];
  const motivo = String(d.motivo ?? '');
  if (!MOTIVOS.includes(motivo)) return corregir('Elige el motivo de la cancelación.');
  cuerpo.motivo = motivo;
}

// ---- 3. Todo listo -------------------------------------------------------------
const c = b.contacto ?? {};
return [{
  json: {
    ...contexto({}),
    valido: true,
    cuerpo,                                       // para POST /cambios-visita
    mensaje_cliente,                              // para WF7 (vacío al cancelar)
    nombre: c.origen === 'solicitud' ? (c.nombre ?? '') : '',   // título del evento (WF5): solo el nombre
    tipo_reforma: b.reforma?.tipo_reforma ?? '',  // título del evento (WF5)
  },
}];

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Traducir la respuesta de POST /cambios-visita (D46). 2026-10-26.
// Mismo patrón que traducir_resultado (ya probado). Textos: sección 4c del Contrato.
// Entrada ($json): { statusCode, body } o { error } si se cortó la conexión.
// Salida (1 elemento), con destino:
//   'calendario' -> hecho (201 o 200): sigue a preparar_calendario_cambio
//   'pantalla'   -> no hecho y se puede corregir: el CONTEXTO, modo 'ficha'
//   'final'      -> no hecho y no hay nada que corregir: el CONTEXTO, modo 'final'
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// La respuesta del backend.
const r = $input.first().json;
const estado = r.statusCode;
const b = r.body ?? {};
// Lo que se envió y el contexto de la pantalla.
const v = $('validar_cambio').first().json;
const enviado = v.cuerpo ?? {};
const op = enviado.oportunidad_id;
const NADA = ' No se ha cambiado nada.';

// Fecha y hora en español y hora de Madrid, solo para MOSTRAR.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit',
    year: 'numeric', hour: '2-digit', minute: '2-digit',
  });
}
// "2026-10-26" + "09:45" -> "26/10/2026 a las 09:45" (sin zonas horarias: se recorta el texto).
const diaHora = (f, h) => (/^\d{4}-\d{2}-\d{2}$/.test(String(f)) ? `${f.slice(8, 10)}/${f.slice(5, 7)}/${f.slice(0, 4)} a las ${h}` : '');
// Motivos del backend -> texto para administración.
const MOTIVOS = { precio: 'precio', plazo: 'plazo', proyecto_no_viable: 'proyecto no viable', otro: 'otro' };

// El contexto común (sin cuerpo ni datos de envío: solo lo de la pantalla).
function ctx(extra) {
  return { destino: 'pantalla', modo: 'ficha', oportunidad_id: v.oportunidad_id, ultima: v.ultima, base: v.base,
    fecha_extra: v.fecha_extra, borrador: v.borrador, avisos: [], final: null,
    aviso_tecnico: false, nodo_error: '', mensaje_tecnico: '', ...extra };
}
// Volver a la pantalla con un aviso. limpiarHora: la hora nueva elegida ya no vale.
function pantalla(aviso, limpiarHora = false, tecnico = false, mensaje_tecnico = '') {
  const borrador = limpiarHora ? { ...v.borrador, fecha: '', hora: '' } : v.borrador;
  return [{ json: ctx({ avisos: [aviso], borrador, aviso_tecnico: tecnico,
    nodo_error: tecnico ? 'registrar_cambio' : '', mensaje_tecnico }) }];
}
// Pantalla final (tipo 'ok' = verde y sigue al calendario; 'aviso' = naranja).
function final(titulo, mensaje, tipo = 'aviso', tecnico = false, mensaje_tecnico = '') {
  return [{ json: ctx({ destino: tipo === 'ok' ? 'calendario' : 'final', modo: 'final',
    final: { titulo, mensaje, tipo }, aviso_tecnico: tecnico,
    nodo_error: tecnico ? 'registrar_cambio' : '', mensaje_tecnico }) }];
}

// ---- 0. Sin respuesta: puede que se haya hecho o no ---------------------------
if (r.error) {
  const e = r.error;
  const detalle = typeof e === 'string' ? e : [e.code, e.message].filter((x) => typeof x === 'string').join(' · ');
  return final('No se sabe si se ha cambiado',
    'Se ha perdido la conexión con el sistema. Vuelve a abrir la pantalla con el mismo número: si la visita ya ' +
    'tiene la hora nueva (o ya no aparece), se hizo; si no, puedes repetirlo sin riesgo de duplicarlo. ' +
    'Si se hizo, el cliente NO ha recibido el email: avísale por teléfono.',
    'aviso', true, `Sin respuesta durante POST /cambios-visita; NO se sabe si se hizo: ${detalle || 'sin detalle'}`);
}

// ---- 1. Éxito: 201 (hecho ahora) o 200 (repetición exacta) -------------------
if (estado === 201 || estado === 200) {
  // La visita de antes, tal como la veía el operador.
  const antes = diaHora(enviado.fecha_actual, enviado.hora_actual);
  if (b.accion === 'cancelar') {
    // 200: ya estaba cancelada con el mismo motivo (normal tras un reintento o una recarga).
    if (estado === 200) return final('Ya estaba cancelada', `Oportunidad ${op}: esta cancelación ya estaba hecha. No se ha cambiado nada.`, 'ok');
    return final('Visita cancelada', `Oportunidad ${op}: visita del ${antes} cancelada, motivo: ${MOTIVOS[b.motivo] ?? b.motivo}. ` +
      'La oportunidad queda cerrada como perdida.', 'ok');
  }
  // cambiar. 200: ya estaba cambiada a esa hora.
  if (estado === 200) return final('Ya estaba cambiada', `Oportunidad ${op}: la visita ya tenía la nueva hora (${fecha(b.fecha_visita)}). No se ha cambiado nada.`, 'ok');
  // La nueva, con el MISMO formato que la de antes (recortada del texto que da el backend).
  const nueva = diaHora(String(b.fecha_visita ?? '').slice(0, 10), String(b.fecha_visita ?? '').slice(11, 16));
  return final('Visita cambiada', `Oportunidad ${op}: la visita pasa del ${antes} al ${nueva}.`, 'ok');
}

// ---- 2. Errores que se corrigen en la pantalla (todo lo escrito se conserva) --
const motivo = b.detail?.motivo;                          // el motivo del error que da el backend
const mensajeBackend = String(b.detail?.mensaje ?? '');
if (estado === 409 && motivo === 'visita_cambiada') {
  // Otra persona la cambió: la pantalla vuelve a leer la ficha y ya enseña la visita nueva.
  return pantalla(`La visita ya no es la que veías: alguien la ha cambiado mientras tanto.${NADA} Revisa la pantalla, que ya está al día, y vuelve a elegir.`, true);
}
if (estado === 409 && motivo === 'hueco_ocupado') {
  return pantalla(`La hora ${diaHora(enviado.fecha, enviado.hora)} se acaba de ocupar por otra visita.${NADA} Elige otra con el cliente; lo demás sigue escrito.`, true);
}
if (estado === 422 && motivo === 'misma_hora_actual') {
  return pantalla(`Es la misma hora que ya tiene: elige otra.${NADA}`, true);
}
// D45: antelacion_insuficiente también (por ejemplo, la pantalla se abrió antes de medianoche y se envió después).
if (estado === 422 && ['fecha_pasada', 'fin_de_semana', 'fuera_de_franja', 'antelacion_insuficiente'].includes(motivo)) {
  return pantalla(`${mensajeBackend}${NADA} Elige otro día u otra hora.`, true);
}
if (estado === 422 && motivo === 'fuera_de_rejilla') {
  // No debería pasar nunca (las horas salen de /huecos-libres): fallo de la pantalla -> aviso técnico.
  return pantalla(`Esa hora no es válida.${NADA} Elige otra; el responsable técnico ya ha recibido un aviso.`, true, true,
    'POST /cambios-visita respondió 422 fuera_de_rejilla: la pantalla ofreció una hora fuera de la rejilla.');
}

// ---- 3. Errores sin nada que corregir: pantalla final -------------------------
const MENSAJES = {
  sin_visita_confirmada: 'Esta oportunidad no tiene ninguna visita confirmada que cambiar o cancelar.',
  visita_pasada: 'La visita ya ha empezado o ha pasado: no se puede cambiar ni cancelar.',
  visita_ya_cancelada: 'Esta visita ya se canceló (la oportunidad está cerrada como perdida).',
  oportunidad_no_encontrada: 'Oportunidad no encontrada.',
};
if (MENSAJES[motivo]) return final('No se ha podido cambiar', MENSAJES[motivo] + NADA);
// Errores técnicos (401, 422 de formato, 503, 500): aviso al responsable técnico (solo códigos, nunca el cuerpo).
const TECNICOS = { 401: 'Error de configuración', 422: 'Error en los datos enviados', 503: 'Sistema no disponible' };
return final(TECNICOS[estado] ?? 'Error inesperado', `El sistema no ha aceptado el cambio (código ${estado}).${NADA} ` +
  'El responsable técnico ya ha recibido un aviso.', 'aviso', true,
  `POST /cambios-visita respondió ${estado}${motivo ? ` (${motivo})` : ''}.`);

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Preparar las llamadas a WF5 tras un cambio de visita (D46). 2026-10-26.
// Copia de preparar_calendario (ya probado), leyendo registrar_cambio y validar_cambio.
// Lo decide la RESPUESTA del backend (mismos nombres que POST /resultados-llamada):
//   visita_cancelada_id  -> WF5 'borrar' la visita vieja      (cambiar y cancelar: siempre viene)
//   visita_id            -> WF5 'guardar' la nueva confirmada (solo cambiar)
// También en un 200 (repetición): WF5 no duplica nunca, y así se recupera un
// calendario que falló la primera vez.
// Salida: 1 elemento por llamada a WF5 (borrar primero, guardar después).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// La respuesta del cambio.
const resp = $('registrar_cambio').first().json;
const b = resp.body ?? {};                            // el cuerpo ("?? {}": vacío si no hay)
// Nombre y tipo de reforma, leídos de la ficha en validar_cambio.
const v = $('validar_cambio').first().json;

// Lo común a todas las llamadas (RGPD: solo el nombre, nunca el contacto ni la dirección).
const comun = {
  nombre: v.nombre ?? '',
  tipo_reforma: v.tipo_reforma ?? '',
  oportunidad_id: b.oportunidad_id ?? v.oportunidad_id,
};

const llamadas = [];                                  // las llamadas a WF5, en orden
// 1. La visita de antes: su evento verde se borra.
if (b.visita_cancelada_id) {
  llamadas.push({ accion: 'borrar', visita_id: b.visita_cancelada_id, estado_visita: '', inicio: '', fin: '', ...comun });
}
// 2. La visita nueva (solo al cambiar): se crea su evento. Inicio y fin, tal cual los da el backend (D33).
if (b.visita_id) {
  llamadas.push({ accion: 'guardar', visita_id: b.visita_id, estado_visita: 'confirmada',
    inicio: b.fecha_visita ?? '', fin: b.fecha_fin_visita ?? '', ...comun });
}
// Un elemento por llamada: llamar_calendario_cambio (modo "each") llama a WF5 una vez por cada uno.
// (Con 201 o 200 siempre viene visita_cancelada_id: la lista nunca está vacía.)
return llamadas.map((j) => ({ json: j }));

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Texto de la pantalla final tras un cambio de visita (D46). 2026-10-26.
// Mismo patrón que cerrar_pantalla (ya probado).
// Entrada: 1 resultado de WF5 por llamada (llamar_calendario_cambio): { ok, ... }, o { error }
//   si WF5 no se pudo ni ejecutar.
// Salida: el CONTEXTO en modo 'final' para construir_pagina (por vuelta_cambio).
//   aviso_tecnico = true SOLO si WF5 no se ejecutó (si se ejecutó y falló, ya avisó él).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// El contexto y el texto del cambio (traducir_cambio).
const t = $('traducir_cambio').first().json;
// La respuesta (para saber la acción y si sale el email).
const resp = $('registrar_cambio').first().json;
const cancelar = resp.body?.accion === 'cancelar';
// ¿Sale el email con la nueva fecha? La MISMA condición que el nodo email_cambio (solo con el 201).
const saleEmail = resp.statusCode === 201 && resp.body?.accion === 'cambiar' && !!resp.body?.visita_id;
const lineaEmail = saleEmail ? ' Se envía al cliente un email con la nueva fecha.'
  : cancelar ? ' Al cliente no se le envía ningún email: si hace falta, avísale tú.' : '';

// Atajo para la salida: el contexto de traducir_cambio con su pantalla final.
function salida(titulo, mensaje, tipo, tecnico = false, mensaje_tecnico = '') {
  return [{ json: { ...t, modo: 'final', final: { titulo, mensaje, tipo },
    aviso_tecnico: tecnico, nodo_error: tecnico ? 'llamar_calendario_cambio' : '', mensaje_tecnico } }];
}

// Lo que se pidió a WF5 y lo que contestó, en el mismo orden.
const pedidas = $('preparar_calendario_cambio').all().map((i) => i.json);
const resultados = $input.all().map((i) => i.json);

// Texto de un error de n8n sin enviar el objeto entero (podría llevar datos).
function textoError(e) {
  if (!e) return 'sin detalle';                                  // no llegó nada
  if (typeof e === 'string') return e;                           // ya es un texto
  const partes = [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '');
  return partes.length > 0 ? partes.join(' · ') : 'error sin texto';
}

// Fallo de la LLAMADA (WF5 no llegó a ejecutarse) o fallo DENTRO de WF5 (ok = false; ya avisó él).
const falloLlamada = resultados.length !== pedidas.length || resultados.some((r) => typeof r.ok !== 'boolean');
const falloWf5 = resultados.some((r) => r.ok === false);
if (falloLlamada || falloWf5) {
  // El cambio SÍ está hecho: que nadie lo repita, y que se sepa que el calendario no cuadra.
  const titulo = cancelar ? 'Visita cancelada, pero el evento sigue en el calendario' : 'Visita cambiada, pero el calendario NO está al día';
  const mensaje = `${t.final.mensaje}${lineaEmail} ⚠️ El cambio SÍ está guardado: no lo repitas. ` +
    'No se ha podido actualizar el calendario "Visitas técnicas — Reformas Amedida": el responsable técnico ya ha recibido un aviso.';
  // Solo si WF5 no se ejecutó hace falta que este flujo avise (si no, WF4 llegaría dos veces).
  const tecnico = falloLlamada
    ? `WF5 no se pudo ejecutar (${resultados.length} de ${pedidas.length} respuestas): ` + resultados.map((r) => textoError(r.error)).join(' | ')
    : '';
  return salida(titulo, mensaje, 'aviso', falloLlamada, tecnico);
}

// Todo bien: la frase del calendario según la acción.
const frase = cancelar
  ? ' La visita se ha quitado del calendario.'
  : ' Calendario actualizado: la hora anterior se ha quitado y la nueva está añadida.';
// Pantalla final verde: el texto del cambio + la frase del calendario + la del email.
return salida(t.final.titulo, t.final.mensaje + frase + lineaEmail, 'ok');

// ---------------------------------------------------------------------------
// Pantalla de llamadas · Vuelta del camino de los cambios de visita (D46). 2026-10-26.
// Junta en UN solo nodo las cuatro salidas del camino nuevo que acaban pintando la pantalla:
//   es_cambio_visita (no)      -> "Actualizar horas" u "Otro día" (POST)
//   cambio_valido (no)         -> lo enviado no vale: se vuelve a pintar con el aviso
//   segun_traduccion_cambio    -> el backend no lo hizo (p. ej. hora ocupada) o pantalla final
//   cerrar_cambio              -> hecho: pantalla final
// y las manda a "contexto" con UNA sola conexión.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Solo se queda con el primer elemento (cada camino manda uno) y lo pasa tal cual.
return [{ json: $input.first().json }];
